window.__BUNDLE = {"body": "<div class=\"wrap\">\n\n  <section id=\"intro\" class=\"stack\" style=\"gap:28px\">\n    <div data-greeting></div>\n    <div id=\"testStart\" class=\"stack\" style=\"gap:28px\" hidden>\n      <div class=\"stack\">\n        <div class=\"eyebrow\">A test for reflection and self-observation · 10 minutes</div>\n        <h1>Adaptation Compass</h1>\n        <p class=\"slogan\">Where you are in your new country and where to go next</p>\n        <p class=\"lead\">Moving to a new country changes everything: language, daily life, work, your social circle and even how you see yourself. This test will help you understand where you are on your path of adaptation, what has already become a support, and where to take your next step.</p>\n      </div>\n      <div class=\"roles k-roles\">\n        <div class=\"role ka0\"><b>Language</b><span>and connection</span></div>\n        <div class=\"role ka1\"><b>Daily life</b><span>and the system</span></div>\n        <div class=\"role ka2\"><b>Work</b><span>and fulfilment</span></div>\n        <div class=\"role ka3\"><b>People</b><span>and ties</span></div>\n        <div class=\"role ka4\"><b>Energy</b><span>body and rest</span></div>\n        <div class=\"role ka5\"><b>Self</b><span>and meaning</span></div>\n      </div>\n      <div class=\"card stack\">\n        <h3>How it works</h3>\n        <p>There are almost no questions about feelings here, only about what you do. Think back over the last 4 weeks and mark how often each thing really happened. There are no right answers, only your picture as it is now.</p>\n        <p>First, two short questions about your move, then six areas of your new life and a short section about two cultures: yours and the new one. At the end you will get a detailed report with pictures, recommendations and questions to reflect on. You can get the report as a PDF.</p>\n        <div class=\"scale-legend\"><span><b>0</b> never</span><span><b>1</b> 1–2 times</span><span><b>2</b> sometimes</span><span><b>3</b> often</span><span><b>4</b> almost always</span></div>\n      </div>\n      <div data-testinfo></div>\n      <div class=\"stack\">\n        <h3>What is your name?</h3>\n        <div class=\"row\" style=\"align-items:stretch\">\n          <div class=\"field\"><label for=\"nameMe\">Your name</label><input id=\"nameMe\" maxlength=\"30\" autocomplete=\"given-name\" placeholder=\"For example, Anna\"></div>\n        </div>\n        <p class=\"note\">Your name is only used to make your report personal.</p>\n      </div>\n      <div><button class=\"btn\" id=\"startBtn\">Start the test</button></div>\n      <div data-share=\"compact\" style=\"margin-top:8px\"></div>\n    </div>\n  </section>\n\n  <section id=\"quiz\" class=\"stack\" hidden style=\"gap:20px\">\n    <div class=\"stack\" style=\"gap:10px\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <span class=\"eyebrow\" id=\"stepLabel\"></span>\n        <span class=\"eyebrow\" id=\"countLabel\"></span>\n      </div>\n      <div class=\"progress\"><i id=\"prog\" style=\"width:0\"></i></div>\n    </div>\n    <div class=\"stack\" style=\"gap:6px\">\n      <div><span class=\"part-tag\" id=\"partTag\"></span></div>\n      <h2 id=\"roleTitle\"></h2>\n      <p class=\"muted\" id=\"roleSub\"></p>\n    </div>\n    <div class=\"card\" id=\"qlist\" style=\"padding-block:6px\"></div>\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <button class=\"btn ghost\" id=\"back\">Back</button>\n      <button class=\"btn\" id=\"next\" disabled>Next</button>\n    </div>\n  </section>\n\n  <section id=\"result\" hidden>\n    <div class=\"rep\" id=\"report\"></div>\n    <div data-share style=\"margin-top:18px\"></div>\n    <div data-lead></div>\n  </section>\n\n  <div data-disclaimer style=\"margin-top:28px\"></div>\n</div>\n<div class=\"pdf-stage\" id=\"stage\" aria-hidden=\"true\"></div>\n", "scripts": ["/* Настройки сайта, общие для всех тестов */\n// Ссылка веб-приложения Google Apps Script (заканчивается на /exec). Одна на все тесты.\nconst ENDPOINT = 'https://script.google.com/macros/s/AKfycbyizp1XjzNdrUj4WHgj4Vyj81QhjY2D7puqyeY3LaweWB4mePxPhfHCx5fIsfaJy9hV/exec';\n// Адрес сайта после размещения, например 'https://irina-tests.netlify.app/' (нужен для ссылок в PDF)\nconst SITE_URL = 'https://irynawiederkehr-cmd.github.io/tests/';\n// Ссылки на тесты, пока сайт не размещён (используются для кнопки «Поделиться» и блока «Пройди также»).\n// После размещения сайта достаточно заполнить SITE_URL — эти ссылки больше не понадобятся.\nconst TEST_LINKS = {\n  'roza-lyubvi': 'https://claude.ai/artifact/6Nv7pCtqpAd9xoWUkvEwS1',\n  'kompas': 'https://claude.ai/artifact/5TPCgkiVSZEr8H2g8d1UkY'\n};\n// Деловой почтовый адрес и e-mail для «Выходных данных» и «Политики конфиденциальности».\n// ЛИЧНЫЙ АДРЕС ИРИНЫ НЕ УКАЗЫВАТЬ. Пока поля пустые, на страницах стоит временная строка «скоро появятся».\n// address — строки через \\n, например 'Musterstrasse 1\\n8000 Zürich'.\nconst LEGAL = {\n  address: {\n    ru: 'проспект Бажана, 5-Г\\n02121 Киев, Украина',\n    uk: 'просп. Миколи Бажана, 5-Г\\n02121 Київ, Україна',\n    de: 'Mykoly-Bazhana-Prospekt 5-H\\n02121 Kyjiw, Ukraine',\n    en: '5-H Mykoly Bazhana Avenue\\n02121 Kyiv, Ukraine'\n  },\n  email: 'voznesenskaya.iryna@gmail.com', since: '02.10.2026'\n};\n", "const BRAND = 'coach';\nconst TEST_META = { id: 'kompas', name: 'Adaptation Compass' };\nconst TEST_INFO = {\n  why: 'I created this questionnaire to help you take a gentle look at your life in a new country. After a move it is easy to see only what is not working yet. The questionnaire shows both the difficulties and the supports you already have, and helps you choose the next step instead of trying to change everything at once.',\n  gives: [\n    'You will see which of the six areas of your new life have already become a support, and which are still quiet.',\n    'You will understand how you are staying connected to your own culture and to the new one right now.',\n    'You will find out which stage of adaptation you are at, and what helps most at this stage.',\n    'You will get a plan of small steps for 4 weeks and questions to reflect on.'\n  ],\n  next: [\n    'Treat the result gently: it is a snapshot of the last 4 weeks, not a judgement of you.',\n    'Start with one area and one small step, not with everything at once.',\n    'Lean on what already works: your strong areas help lift the others.',\n    'In 4 weeks, take the test again and see what has changed.',\n    'If things get very hard, talk to someone close to you or to a professional.'\n  ]\n};\nconst TEST_DISCLAIMER = ['This questionnaire is a tool for reflection, self-observation and personal growth. It is not a psychological or medical diagnosis or a psychotherapeutic assessment, and it does not replace a consultation with a professional.', null, null];\n", "/* =====================================================================\n   Библиотека значков — общая для всех тестов (с 02.10.2026).\n   Один стиль: сетка 24×24, мягкая заливка светлым тоном + тонкий контур глубоким тоном того же цвета\n   (как акварель с контуром в утверждённой палитре), линия 1.8, скруглённые концы.\n   Использование: ico('flame', '#C25468', '#EEA9B3', 26) — имя, цвет контура, цвет заливки, размер.\n   Если заливка не задана, берётся очень светлый тон контура.\n   Каталог с картинками всех значков — файл «Библиотека значков.html».\n   ===================================================================== */\nconst ICONS = {\n  /* ступени, дом, опоры */\n  earth:    (c, f, s) => `<circle cx=\"12\" cy=\"8\" r=\"3.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M3 15c3-2 6-2 9 0s6 2 9 0M3 19.5c3-2 6-2 9 0s6 2 9 0\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  hearth:   (c, f, s) => `<path d=\"M12 3c3 4 6.5 6 6.5 10.5a6.5 6.5 0 0 1-13 0c0-3 2-4.5 3-6.5 1 2 2 3 3 3 0-3-1-5 .5-7z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M9 21h6\" stroke=\"${c}\" ${s}/>`,\n  door:     (c, f, s) => `<rect x=\"6\" y=\"3\" width=\"12\" height=\"18\" rx=\"1.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"14.8\" cy=\"12.5\" r=\"1.2\" fill=\"${c}\"/><path d=\"M3 21h18\" stroke=\"${c}\" ${s}/>`,\n  key:      (c, f, s) => `<circle cx=\"8\" cy=\"12\" r=\"4.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12.2 12H21M18 12v3M21 12v3\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  workshop: (c, f, s) => `<path d=\"M13.5 4.5l6 6-3 3-6-6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 9l-8 8 3 3 8-8\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  sprout:   (c, f, s) => `<path d=\"M12 21v-9\" stroke=\"${c}\" ${s}/><path d=\"M12 13c-4.5 0-7-3-7-7 4.5 0 7 3 7 7zM12 11c0-4.5 3-7 7.5-7 0 4.5-3 7-7.5 7z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  hill:     (c, f, s) => `<path d=\"M2 19.5l7-9.5 4 5 3-3.5 6 8z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"17\" cy=\"5.5\" r=\"2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  sky:      (c, f, s) => `<path d=\"M12 3l1.9 5.6L19.5 10.5l-5.6 1.9L12 18l-1.9-5.6L4.5 10.5l5.6-1.9z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"19\" cy=\"19\" r=\"1.4\" fill=\"${c}\"/><circle cx=\"5\" cy=\"19.5\" r=\"1\" fill=\"${c}\"/>`,\n  home:     (c, f, s) => `<path d=\"M3.5 11 12 4l8.5 7v9.5h-17z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M10 20.5v-5h4v5\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  homeLight:(c, f, s) => `<path d=\"M3.5 11 12 4l8.5 7v9.5h-17z\" fill=\"none\" stroke=\"${c}\" ${s}/><rect x=\"9\" y=\"11.5\" width=\"6\" height=\"5\" rx=\"1\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 11.5v5M9 14h6\" stroke=\"${c}\" stroke-width=\"1.2\"/>`,\n  /* отношения */\n  flame:    (c, f, s) => `<path d=\"M12 3c3 4 6.5 6 6.5 10.5a6.5 6.5 0 0 1-13 0c0-3 2-4.5 3-6.5 1 2 2 3 3 3 0-3-1-5 .5-7z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 20a2.6 2.6 0 0 1-2.6-2.6c0-1.6 1.4-2.4 2.6-4 1.2 1.6 2.6 2.4 2.6 4A2.6 2.6 0 0 1 12 20z\" fill=\"${c}\" fill-opacity=\".35\"/>`,\n  rings:    (c, f, s) => `<circle cx=\"9\" cy=\"12\" r=\"5.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"15\" cy=\"12\" r=\"5.2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  heart:    (c, f, s) => `<path d=\"M12 20s-7.5-4.6-7.5-10.2A4.3 4.3 0 0 1 12 7.3a4.3 4.3 0 0 1 7.5 2.5C19.5 15.4 12 20 12 20z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  bridge:   (c, f, s) => `<path d=\"M2.5 16.5V13.2C7 9.2 17 9.2 21.5 13.2V16.5H18.4C17.4 14.2 15 13 12 13S6.6 14.2 5.6 16.5Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M2.5 10.4C7 6.4 17 6.4 21.5 10.4\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M6 8.3V11.2M10 7.2V10.2M14 7.2V10.2M18 8.3V11.2\" stroke=\"${c}\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><path d=\"M2.5 20.2C4.5 19.1 6.5 19.1 8.5 20.2S12.5 21.3 14.5 20.2 18.5 19.1 21.5 20.2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  together: (c, f, s) => `<path d=\"M12 6.8A6 6 0 0 1 12 17.2A6 6 0 0 1 12 6.8Z\" fill=\"${f}\"/><circle cx=\"9\" cy=\"12\" r=\"6\" fill=\"none\" stroke=\"${c}\" ${s}/><circle cx=\"15\" cy=\"12\" r=\"6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  trees:    (c, f, s) => `<path d=\"M7.5 21v-5M16.5 21v-5\" stroke=\"${c}\" ${s}/><path d=\"M7.5 16.5c-2.6 0-4.3-2-4.3-4.6S5 6 7.5 4c2.5 2 4.3 5.3 4.3 7.9s-1.7 4.6-4.3 4.6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M16.5 16.5c-2.6 0-4.3-2-4.3-4.6S14 6 16.5 4c2.5 2 4.3 5.3 4.3 7.9s-1.7 4.6-4.3 4.6z\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M3 21h18\" stroke=\"${c}\" ${s}/>`,\n  hands:    (c, f, s) => `<path d=\"M3 13.5l4.5-4 4 2.5 4-2.5 5.5 4-6 5.5h-6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M11.5 12l2.5 2.5M9.5 14l2 2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  speech:   (c, f, s) => `<path d=\"M4 5.5h16v10H10l-5 4v-4H4z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M8 9.5h8M8 12.5h5\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  people:   (c, f, s) => `<circle cx=\"8.5\" cy=\"8.5\" r=\"3\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"16\" cy=\"9.5\" r=\"2.6\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M3 19.5c.6-3.4 2.9-5.3 5.5-5.3s4.9 1.9 5.5 5.3M13.5 15c.8-.5 1.6-.7 2.5-.7 2.3 0 4.3 1.7 4.9 4.6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  shield:   (c, f, s) => `<path d=\"M12 3l7.5 3v5.5c0 4.6-3.2 8-7.5 9.5-4.3-1.5-7.5-4.9-7.5-9.5V6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M9 12l2.2 2.2L15.5 10\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  anchor:   (c, f, s) => `<circle cx=\"12\" cy=\"5.5\" r=\"2.3\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 7.8V20M8 11h8M4.5 14c.5 3.5 3.6 6 7.5 6s7-2.5 7.5-6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  /* путь, рефлексия, эксперимент */\n  compass:  (c, f, s) => `<circle cx=\"12\" cy=\"12\" r=\"8.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M14.8 9.2l-1.8 4.8-4.8 1.8 1.8-4.8z\" fill=\"${c}\" fill-opacity=\".85\" stroke=\"${c}\" stroke-width=\"1.2\" stroke-linejoin=\"round\"/>`,\n  path:     (c, f, s) => `<path d=\"M3 20.5H8V16.5H12V12.5H16V8.5H21V20.5Z\" fill=\"${f}\" stroke=\"none\"/><path d=\"M3 20.5H8V16.5H12V12.5H16V8.5H21\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M18.5 8.5V3\" stroke=\"${c}\" ${s}/><path d=\"M18.5 3.2H22L21 4.6L22 6H18.5\" fill=\"#fff\" stroke=\"${c}\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><circle cx=\"5.5\" cy=\"17.3\" r=\"1.3\" fill=\"${c}\"/>`,\n  telegram: (c, f, s) => `<path d=\"M3.2 11.4L20.2 4.3C20.8 4.1 21.3 4.6 21.2 5.2L18.4 19C18.3 19.6 17.6 19.9 17.1 19.5L12.6 16.2L10.2 18.6C9.9 18.9 9.4 18.7 9.4 18.3V14.8L17 7.8L7.6 13.4L3.4 12.2C2.8 12 2.7 11.6 3.2 11.4Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  instagram:(c, f, s) => `<rect x=\"3.5\" y=\"3.5\" width=\"17\" height=\"17\" rx=\"5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"12\" cy=\"12\" r=\"4\" fill=\"#fff\" stroke=\"${c}\" ${s}/><circle cx=\"16.9\" cy=\"7.1\" r=\"1.1\" fill=\"${c}\"/>`,\n  mail:     (c, f, s) => `<rect x=\"3\" y=\"5.5\" width=\"18\" height=\"13\" rx=\"2.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M3.8 7L12 12.8L20.2 7\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  megaphone:(c, f, s) => `<path d=\"M4 10V14H7L15 18.5V5.5L7 10Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M7 14L8.2 19H10.4L9.6 14\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M18 9.5C19 10.2 19.5 11 19.5 12S19 13.8 18 14.5\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  chatbot:  (c, f, s) => `<path d=\"M5 5H19A2 2 0 0 1 21 7V15A2 2 0 0 1 19 17H11L6.5 20.5V17H5A2 2 0 0 1 3 15V7A2 2 0 0 1 5 5Z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"8.5\" cy=\"11\" r=\"1.2\" fill=\"${c}\"/><circle cx=\"12\" cy=\"11\" r=\"1.2\" fill=\"${c}\"/><circle cx=\"15.5\" cy=\"11\" r=\"1.2\" fill=\"${c}\"/>`,\n  signpost: (c, f, s) => `<path d=\"M12 3v18M8.5 21h7\" stroke=\"${c}\" ${s}/><path d=\"M12 5h6.3l2.2 2.2-2.2 2.2H12z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 11.5H5.7l-2.2 2.2 2.2 2.2H12z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  eye:      (c, f, s) => `<path d=\"M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"12\" cy=\"12\" r=\"3\" fill=\"none\" stroke=\"${c}\" ${s}/><circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"${c}\"/>`,\n  explore:  (c, f, s) => `<circle cx=\"10.5\" cy=\"10.5\" r=\"6\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M15 15l5.5 5.5\" stroke=\"${c}\" ${s}/><path d=\"M8 9.5a2.8 2.8 0 0 1 2.5-2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  flask:    (c, f, s) => `<path d=\"M9.5 3.5v5.5L4.5 18a2 2 0 0 0 1.8 3h11.4a2 2 0 0 0 1.8-3l-5-9V3.5\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M6.8 15h10.4l1.6 3a1.2 1.2 0 0 1-1.1 1.8H6.3A1.2 1.2 0 0 1 5.2 18z\" fill=\"${f}\" stroke=\"${c}\" stroke-width=\"1.2\"/><path d=\"M8 3.5h8\" stroke=\"${c}\" ${s}/>`,\n  mirror:   (c, f, s) => `<ellipse cx=\"12\" cy=\"9.5\" rx=\"5.5\" ry=\"6.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 16v5M8.5 21h7M9.5 7a3 3 0 0 1 2-1.6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  pen:      (c, f, s) => `<path d=\"M15.5 4.5l4 4L9 19l-5 1 1-5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M13.5 6.5l4 4\" stroke=\"${c}\" ${s}/>`,\n  book:     (c, f, s) => `<path d=\"M3.5 5.5c3-1 5.8-.8 8.5 1 2.7-1.8 5.5-2 8.5-1v13c-3-1-5.8-.8-8.5 1-2.7-1.8-5.5-2-8.5-1z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 6.5v13\" stroke=\"${c}\" ${s}/>`,\n  seed:     (c, f, s) => `<path d=\"M12 20c-3.6 0-6-2.6-6-6.3C6 9.5 9 6 12 4c3 2 6 5.5 6 9.7 0 3.7-2.4 6.3-6 6.3z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 20v-7.5\" stroke=\"${c}\" ${s}/>`,\n  sun:      (c, f, s) => `<circle cx=\"12\" cy=\"12\" r=\"4.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 2.8v2.4M12 18.8v2.4M2.8 12h2.4M18.8 12h2.4M5.5 5.5l1.7 1.7M16.8 16.8l1.7 1.7M5.5 18.5l1.7-1.7M16.8 7.2l1.7-1.7\" stroke=\"${c}\" ${s}/>`,\n  moon:     (c, f, s) => `<path d=\"M19 15.5A8 8 0 0 1 8.5 5a8 8 0 1 0 10.5 10.5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  lantern:  (c, f, s) => `<path d=\"M9 6h6l1.5 3v8L15 20H9l-1.5-3V9z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M10 3.5h4M12 3.5V6M12 11v4\" stroke=\"${c}\" ${s}/>`,\n  cup:      (c, f, s) => `<path d=\"M4.5 9h12v5a5 5 0 0 1-5 5h-2a5 5 0 0 1-5-5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M16.5 10.5h1.5a2.3 2.3 0 0 1 0 4.6h-1.8M8 3.5c-.8 1 .8 2-.1 3M12 3.5c-.8 1 .8 2-.1 3\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  mask:     (c, f, s) => `<path d=\"M4 6.5c5-2 11-2 16 0v5.5c0 4.5-3.6 8-8 8s-8-3.5-8-8z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M7.5 11c1-.8 2.5-.8 3.5 0M13 11c1-.8 2.5-.8 3.5 0M9 15.5c1.8 1.2 4.2 1.2 6 0\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  lock:     (c, f, s) => `<rect x=\"5\" y=\"10.5\" width=\"14\" height=\"10\" rx=\"2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M8 10.5V8a4 4 0 0 1 8 0v2.5M12 14.5v2.5\" fill=\"none\" stroke=\"${c}\" ${s}/>`\n};\n/* светлый тон цвета для заливки по умолчанию */\nconst icoSoft = c => { const h = String(c).replace('#', ''); if (h.length !== 6) return 'none';\n  return '#' + [0, 2, 4].map(i => Math.round(parseInt(h.substr(i, 2), 16) * .3 + 255 * .7).toString(16).padStart(2, '0')).join(''); };\nfunction ico(name, line = '#2E5A88', fill, size = 24){\n  const draw = ICONS[name] || ICONS.seed;\n  const s = 'stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"';\n  return `<svg viewBox=\"0 0 24 24\" width=\"${size}\" height=\"${size}\" aria-hidden=\"true\">${draw(line, fill || icoSoft(line), s)}</svg>`;\n}\n\n/* знак-аватар Ирины: цветок-мандала (с 03.10.2026) */\nconst AVATAR_SVG = '<svg viewBox=\"0 0 100 100\" aria-hidden=\"true\"><circle cx=\"50\" cy=\"50\" r=\"46\" fill=\"#FFFCF8\" stroke=\"#6E4F3C\" stroke-width=\"3\"/><g transform=\"rotate(22.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(67.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(112.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(157.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(202.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(247.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(292.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(337.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(0.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(45.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(90.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(135.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(180.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(225.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(270.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(315.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><circle cx=\"50\" cy=\"50\" r=\"7\" fill=\"#B98324\"/></svg>';\n", "/* язык страницы: задаёт загрузчик (ru, uk, de, en) */\nconst DATE_LOCALE = ({ ru:'ru-RU', uk:'uk-UA', de:'de-CH', en:'en-GB' })[(typeof LANG !== 'undefined') ? LANG : 'ru'] || 'ru-RU';\n/* =====================================================================\n   Общие тексты и блоки для всех тестов Ирины Вознесенской.\n   Меняешь здесь — меняется во всех тестах сразу.\n   ===================================================================== */\n\n/* ---------- Обо мне и контакты ---------- */\nconst AUTHOR = {\n  name: 'Iryna Voznesenskaya',\n  about: 'ICF coach in Switzerland and psychologist in Ukraine.',\n  coach: { place: 'Switzerland · Zurich', title: 'Coach', badge: \"Transformational coach and neurocoach, ICF\", text: [\"I support people who, for many different reasons, have left their country and are now building a life anew in a new place. I know how much strength this takes: stress that lingers even after the papers are sorted, unfamiliar rules, a language in which you cannot yet say what matters most, and the quiet feeling that, along with your home, you left a part of yourself behind.\", \"In our work we go deep, through emotional intelligence, to where your reactions and decisions are born. That is why change happens from the inside and stays with you. Step by step you begin to feel you belong in a foreign country, find your place, gently rebuild your sense of self and are, in a way, born anew here to live your happy life.\"], legal: \"In Switzerland I work only as a coach. Coaching is not psychotherapy and does not replace psychological or medical care.\",\n           instagram: 'https://www.instagram.com/iryna.voznesenskaya/', telegram: 'https://t.me/IrynaNeuroCoach_channel' },\n  psy:   { place: 'Ukraine · Kyiv', title: 'Psychologist in Ukraine', badge: \"Psychologist · C. G. Jung’s analytical psychology\", text: [\"I work with people for whom living, warm relationships matter. Love often does not disappear; it simply grows quiet under fatigue, hurt and everyday routine, and each partner is left alone with their pain.\", \"I work at the depth of unconscious processes: through deep dialogue, metaphor, images and symbols, drawing on Carl Jung’s analytical psychology. This brings to light what is hard to put into words, and gives a couple the chance to hear each other again and bring back closeness and warmth.\"], legal: \"As a psychologist I work only with clients in Ukraine, based on my Ukrainian qualification.\",\n           instagram: 'https://www.instagram.com/voznesenskayairyna.psy/', telegram: 'https://t.me/IrynaVoznesenska_psy' }\n};\n\n/* ---------- Все тесты (для главной и блока «Пройди также») ---------- */\nconst TESTS = [\n  { id: 'roza-lyubvi', path: 'roza-lyubvi/', name: 'The Rose of Love', slogan: 'To hear each other again and bring warmth back to your relationship', brand: 'psy', tag: 'For couples · 15 minutes',\n    text: 'Three roles in a couple: attraction, closeness and commitment. Find out which roles are vivid, which have gone quieter, and how you meet each other.' },\n  { id: 'kompas', path: 'kompas/', name: 'Adaptation Compass', slogan: 'Where you are in your new country and where to go next', brand: 'coach', tag: 'For yourself · 10 minutes',\n    text: 'Where you are now after moving: six areas of your new life, your path between two cultures and your next small step.' }\n];\n\nconst handle = url => '@' + url.replace(/\\/+$/, '').split('/').pop();\nconst pickOne = arr => arr[Math.floor(Math.random() * arr.length)];\nconst BASE = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n\nfunction practiceHtml(key){\n  const p = AUTHOR[key];\n  const links = [\n    p.instagram ? `<a href=\"${p.instagram}\" target=\"_blank\" rel=\"noopener\">${ico('instagram', '#C25468', null, 18)} Instagram ${handle(p.instagram)}</a>` : '',\n    p.telegram ? `<a href=\"${p.telegram}\" target=\"_blank\" rel=\"noopener\">${ico('telegram', '#3F6FBF', null, 18)} Telegram channel</a>` : ''\n  ].filter(Boolean).join('');\n  return `<div class=\"practice ${key}\"><span class=\"place\">${p.place}</span><h4>${p.title}</h4>${p.badge ? `<span class=\"pbadge\">${p.badge}</span>` : ''}${[].concat(p.text).map(t => `<p>${t}</p>`).join('')}${p.legal ? `<p class=\"plegal\">${p.legal}</p>` : ''}<div class=\"links\">${links}</div></div>`;\n}\nfunction authorHtml(label = 'About the author'){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  return `<div class=\"blk author\"><div class=\"eyebrow\">${label}</div>\n    <div class=\"who\"><div class=\"mono av\">${AVATAR_SVG}</div><div><b>${AUTHOR.name}</b><span>${AUTHOR.about}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div></div>`;\n}\nfunction footerLine(){\n  return BRAND === 'coach' ? 'Iryna Voznesenskaya · ICF coach (Switzerland) · psychologist (Ukraine)' : 'Iryna Voznesenskaya · psychologist (Ukraine) · ICF coach (Switzerland)';\n}\n\n/* ---------- Приветствие и обязательный мини-опрос ---------- */\nconst SURVEY = {\n  heard: { q: 'How did you hear about me?', opts: ['Instagram','Telegram','Recommended by friends or acquaintances','Google search','Facebook','Other'] },\n  interest: { q: 'What are you interested in?', opts: ['Psychology: couple relationships','Coaching: adapting after moving abroad and finding yourself','Just curious for now'] }\n};\nconst GREET = {\n  head: ['Hi! I’m {A}','Glad you’re here! My name is {A}','Welcome! I’m {A}','Hello! I’m {A}'],\n  about: ['ICF coach in Switzerland and psychologist in Ukraine.','I work in two countries: as an ICF coach in Switzerland and as a psychologist in Ukraine.','I help people find themselves and build warm relationships: as an ICF coach in Switzerland and as a psychologist in Ukraine.'],\n  ask: ['Before the test, please answer three short questions. This helps me understand how I can be useful to you.',\n        'Three short questions before we start, and then straight to the test.',\n        'It matters to me to know who comes to my tests. Please answer three short questions.']\n};\nfunction greetingHtml(){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  const group = key => `<fieldset class=\"survey\"><legend>${SURVEY[key].q} *</legend>${SURVEY[key].opts.map((o, i) =>\n    `<label class=\"check\"><input type=\"checkbox\" id=\"sv-${key}-${i}\" data-sv=\"${key}\" value=\"${o}\"> <span>${o}</span></label>`).join('')}</fieldset>`;\n  return `<div class=\"blk author greet\">\n    <div class=\"who\"><div class=\"mono av\">${AVATAR_SVG}</div><div><b>${pickOne(GREET.head).replace('{A}', AUTHOR.name)}</b><span>${pickOne(GREET.about)}</span></div></div>\n    <p class=\"greet-more\"><a href=\"${BASE}#about\">More about me and how I work →</a></p>\n    <div class=\"stack\" style=\"gap:10px\"><p class=\"note\">${pickOne(GREET.ask)} You can choose more than one option.</p>\n      <div class=\"surveys\">${group('heard')}${group('interest')}</div>\n      <p class=\"err\" id=\"svErr\" hidden></p>\n      <div><button class=\"btn\" type=\"button\" id=\"svGo\">Go to the test</button></div></div></div>`;\n}\nfunction surveyAnswers(){\n  const pick = key => [...document.querySelectorAll(`input[data-sv=\"${key}\"]:checked`)].map(i => i.value);\n  return { heard: pick('heard'), interest: pick('interest') };\n}\n\n/* ---------- Живое приглашение в работу (тексты каждый раз собираются заново) ---------- */\nconst INVITES = {\n  psy: {\n    open: ['{N}, thank you for your honest answers.',\n           '{N}, you are already taking an important step: looking honestly at your relationship.',\n           '{N}, this report is only the beginning of a conversation.',\n           '{N}, the test shows a picture, but real change begins in conversation.',\n           '{N}, behind every number in this report is your own story.'],\n    body: ['The numbers show where things have gone quiet in your couple. But behind them there is always something personal: tiredness, hurt, habits, unspoken expectations. In our meeting we will gently look at your situation and find the first steps to {F}.',\n           'Sometimes one precise question is enough for a couple to hear each other again. If you would like to {F}, I invite you to a meeting: calm, gentle, without judgement.',\n           'Relationships change not through knowledge, but through new actions. I help couples find these actions and not give them up after a week. Let’s look together at how to {F}.',\n           'You can move towards change on your own, or with support. In our meeting we will discuss your triangle and outline how to {F}.',\n           'Many couples live with the same tension for years because they don’t know how to start the conversation. I will help you start it in a way that helps you {F}.'],\n    cta:  ['Book a 30-minute introductory meeting: we will discuss your result and decide whether further work on your relationship is needed.',\n           '30 minutes online. You talk, I listen and ask questions. After the meeting it will be clearer what is happening in your couple and where to start.',\n           'The first meeting lasts 30 minutes. That is enough to understand what you need and to map out how to work on your relationship.'],\n    title: ['I invite you to a 30-minute meeting','Let’s talk about your relationship','The next step is a conversation'],\n    legal: 'Psychologist consultations are held online for clients in Ukraine.'\n  },\n  coach: {\n    open: ['{N}, thank you for making time for yourself.',\n           '{N}, you are already taking an important step: looking at yourself honestly and gently.',\n           '{N}, this report is only the beginning of the journey.',\n           '{N}, sometimes one test opens up more questions than answers. And that is good.',\n           '{N}, everything you see now can be turned into support.'],\n    body: ['Moving to a new country changes everything: language, habits, roles in the family and even how we see ourselves. In coaching we look for what supports you in the new world and, step by step, help you {F}.',\n           'When the country changes, we change too. Sometimes it feels like losing yourself. I help you find yourself again so that you can {F}.',\n           'You have already come a long way. Coaching helps you turn this experience into strength and {F}.',\n           'The answers are already within you, but they are hard to hear in the bustle of a new life. Working with me, you will find your own answers and decide how to {F}.',\n           'Adaptation is not only about documents and language. It is about finding your place. Let’s look together at how to {F}.'],\n    cta:  ['Book a 30-minute introductory meeting: we will talk about what you need and what working on yourself could look like.',\n           '30 minutes online. You tell me what matters to you right now, and I ask questions. After the meeting it will be clearer where to go next.',\n           'The first meeting lasts 30 minutes. That is enough to understand what you need and to map out the first steps.'],\n    title: ['I invite you to a 30-minute meeting','Let’s talk about you','The next step is a conversation'],\n    legal: 'Coaching is not psychotherapy and does not replace psychological or medical care.'\n  }\n};\nconst INVITE_FOCUS_DEFAULT = { psy: 'bring more warmth and understanding into your relationship', coach: 'find your place in the new world' };\nlet inviteSeed = null;\nfunction resetInvite(){ inviteSeed = null; }\nfunction invitePractice(country){\n  // как психолог Ирина работает только с клиентами в Украине; остальных приглашаем в коучинг\n  if (BRAND === 'psy' && country && country !== 'Украина') return 'coach';\n  return BRAND;\n}\nfunction inviteHtml(ctx){\n  if (!inviteSeed) inviteSeed = Array.from({length:6}, () => Math.random());\n  const key = invitePractice(ctx.country);\n  const P = INVITES[key], A = AUTHOR[key];\n  const pick = (arr, i) => arr[Math.floor(inviteSeed[i] * arr.length)];\n  const N = ctx.name || '';\n  const F = (ctx.focus && ctx.focus[key]) || INVITE_FOCUS_DEFAULT[key];\n  const fill = t => { let s = N ? t.replace('{N}', N) : t.replace('{N}, ', ''); s = s.replace('{F}', F); return s.charAt(0).toUpperCase() + s.slice(1); };\n  const links = [A.telegram ? `<a href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram: ${A.telegram.replace('https://','')}</a>` : '',\n                 A.instagram ? `<a href=\"${A.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram: ${handle(A.instagram)}</a>` : ''].filter(Boolean);\n  const other = key === 'psy' ? 'coach' : 'psy';\n  const wantsOther = (ctx.interest || []).some(x => other === 'coach' ? /^Coaching/.test(x) : /^Psycholog/.test(x));\n  const otherLine = wantsOther && !(other === 'psy' && ctx.country && ctx.country !== 'Украина')\n    ? `<p class=\"note\">You are also interested in my work as a ${AUTHOR[other].title.replace(/^./, c => c.toLowerCase())}. You can find out more about it here: <a href=\"${AUTHOR[other].telegram}\" target=\"_blank\" rel=\"noopener\">${AUTHOR[other].telegram.replace('https://','')}</a></p>` : '';\n  return `<div class=\"blk invite ${key}\">\n    <div class=\"eyebrow\">${key === 'psy' ? 'Working on your relationship' : 'Working on yourself'}</div>\n    <h2>${pick(P.title, 0)}</h2>\n    <p class=\"lead\"><b>${fill(pick(P.open, 1))}</b></p>\n    <p>${fill(pick(P.body, 2))}</p>\n    <div class=\"invite-cta\"><p>${fill(pick(P.cta, 3))}</p>\n      <p><b>How to book:</b> send me the word <b>“MEETING”</b>, and I will suggest a convenient time.</p>\n      <div class=\"invite-links\">${links.join('')}</div></div>\n    ${otherLine}\n    <p class=\"note\">${P.legal}</p></div>`;\n}\n\n/* ---------- Пройди также ---------- */\nfunction testUrl(t){\n  if (typeof SITE_URL !== 'undefined' && SITE_URL) return SITE_URL.replace(/\\/?$/, '/') + t.path;\n  if (typeof TEST_LINKS !== 'undefined' && TEST_LINKS[t.id]) return TEST_LINKS[t.id];\n  return BASE + t.path;\n}\nfunction moreTestsHtml(currentId){\n  const list = TESTS.filter(t => t.id !== currentId);\n  if (!list.length) return '';\n  return `<div class=\"blk more\"><div class=\"eyebrow\">Also try</div>\n    <div class=\"tcards\">${list.map(t => `<a class=\"tcard ${t.brand}\" href=\"${testUrl(t)}\" target=\"_blank\" rel=\"noopener\">\n      <span class=\"ttag\">${t.tag}</span><b>${t.name}</b><span class=\"tslogan\">${t.slogan}</span><span>${t.text}</span><span class=\"tgo\">Take the test →</span></a>`).join('')}</div></div>`;\n}\n\n/* ---------- Об этом опроснике + дисклеймер ---------- */\nconst DISCLAIMER = [\n  'This questionnaire is a tool for reflection, self-observation and personal growth, and a starting point for conversation. It is not a psychological or medical diagnosis or a psychotherapeutic assessment, and it does not replace a consultation with a professional.',\n  'The results reflect your personal perception over the last 4 weeks and may change.',\n  'If you are going through a crisis, violence or a threat to your safety, please contact a professional or the emergency services in your country.'\n];\n/* Точка А → точка Б: если в TEST_INFO есть from / to / key — показываем, с чем человек приходит и с чем уходит. */\nfunction abHtml(){\n  if (typeof TEST_INFO === 'undefined' || !TEST_INFO.from) return '';\n  const ps = a => [].concat(a).map(x => `<p>${x}</p>`).join('');\n  return `<div class=\"ab\"><div class=\"ab-a\"><span class=\"ab-l\">Point A · where you start</span>${ps(TEST_INFO.from)}</div>\n    <div class=\"ab-arrow\" aria-hidden=\"true\"><svg viewBox=\"0 0 40 24\" width=\"40\" height=\"24\"><path d=\"M2 12h32M26 4l8 8-8 8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div>\n    <div class=\"ab-b\"><span class=\"ab-l\">Point B · what you leave with</span>${ps(TEST_INFO.to)}</div></div>\n    ${TEST_INFO.key ? `<div class=\"ab-key\"><b>The key insight</b><p>${TEST_INFO.key}</p></div>` : ''}`;\n}\nfunction testInfoHtml(){\n  if (typeof TEST_INFO === 'undefined') return '';\n  if (TEST_INFO.from) return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Why take it</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>${abHtml()}\n    <div class=\"ti-cols\"><div><h3>What to do with it</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div></div></div>`;\n  return `<div class=\"blk testinfo\"><div class=\"eyebrow\">About this questionnaire</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\">\n      <div><h3>What it gives you</h3><ul class=\"clean\">${TEST_INFO.gives.map(x => `<li>${x}</li>`).join('')}</ul></div>\n      <div><h3>What to do with it</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div>\n    </div></div>`;\n}\n/* Текст «Важно» сверяется по смыслу с каждым тестом: свой вариант — TEST_DISCLAIMER в meta.js (null = общая строка). */\nfunction disclaimerHtml(list){\n  const D = list || (typeof TEST_DISCLAIMER !== 'undefined' ? TEST_DISCLAIMER.map((x, i) => x || DISCLAIMER[i]).filter(Boolean) : DISCLAIMER);\n  return `<div class=\"disclaimer\"><b>Important</b>${D.map(x => `<p>${x}</p>`).join('')}</div>`;\n}\n\n/* ---------- Поделиться тестом ---------- */\nconst SHARE_TEXT = {\n  'roza-lyubvi': ['I took “The Rose of Love” test for couples: interesting and very accurate. Take it too, then we can compare:',\n                  'I found “The Rose of Love” test: 15 minutes, and you can see which roles in your couple are vivid and which have gone quieter. Give it a try:'],\n  'kompas':      ['I took the “Adaptation Compass” test for people living abroad. It really helps you see where you are now. Give it a try:',\n                  'I found the “Adaptation Compass” test: 10 minutes, and you can see what has already become a support in the new country and what is still quiet. Give it a try:']\n};\nconst SHARE_ICON = {\n  share: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 8l5-5 5 5M5 13v6a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  wa: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 20l1.2-4A8 8 0 1 1 8 18.8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 1c-1-.5-1.5-1-2-2l1-1-1-2z\" fill=\"currentColor\"/></svg>',\n  tg: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 4 3 11l6 2 2 6 3-4 5 4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"m9 13 8-6\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>',\n  copy: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>'\n};\nfunction shareData(){\n  const t = TESTS.find(x => typeof TEST_META !== 'undefined' && x.id === TEST_META.id) || TESTS[0];\n  return { url: testUrl(t), text: pickOne(SHARE_TEXT[t.id] || ['Try this test:']), title: t.name };\n}\nfunction shareHtml(compact){\n  if (typeof TEST_META === 'undefined') return '';\n  const head = compact\n    ? `<p class=\"note\">Know someone who might find this test useful too? Send them the link.</p>`\n    : `<div class=\"eyebrow\">Share</div><h3>Send the test to friends</h3><p>If the test was useful, send it to people it might help too. ${TEST_META.id === 'roza-lyubvi' ? 'Even better, invite your partner to take it and compare your results.' : 'Especially to those who have also recently moved.'}</p>`;\n  return `<div class=\"${compact ? 'share compact' : 'blk share'}\">${head}\n    <div class=\"share-btns\">\n      ${navigator.share ? `<button type=\"button\" class=\"main\" data-share-act=\"native\">${SHARE_ICON.share}Share</button>` : ''}\n      <button type=\"button\" data-share-act=\"wa\">${SHARE_ICON.wa}WhatsApp</button>\n      <button type=\"button\" data-share-act=\"tg\">${SHARE_ICON.tg}Telegram</button>\n      <button type=\"button\" data-share-act=\"copy\">${SHARE_ICON.copy}Copy link</button>\n    </div>\n    <div class=\"share-link\" hidden><input readonly aria-label=\"Link to the test\"></div>\n    <span class=\"share-ok\" hidden></span></div>`;\n}\nfunction openExternal(url){\n  const w = window.open(url, '_blank', 'noopener');\n  if (!w) location.href = url;\n}\ndocument.addEventListener('click', async (ev) => {\n  const b = ev.target.closest('[data-share-act]'); if (!b) return;\n  const box = b.closest('.share'), d = shareData(), act = b.dataset.shareAct;\n  const ok = box.querySelector('.share-ok');\n  const showOk = t => { ok.textContent = t; ok.hidden = false; setTimeout(() => ok.hidden = true, 4000); };\n  if (act === 'native'){\n    try { await navigator.share({ title: d.title, text: d.text, url: d.url }); return; }\n    catch(e){ if (e && e.name === 'AbortError') return; }\n  }\n  if (act === 'wa') return openExternal('https://wa.me/?text=' + encodeURIComponent(d.text + ' ' + d.url));\n  if (act === 'tg') return openExternal('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.text));\n  try { await navigator.clipboard.writeText(d.text + ' ' + d.url); showOk('Link copied. Paste it into a message to a friend.'); }\n  catch(e){\n    const row = box.querySelector('.share-link'), inp = row.querySelector('input');\n    inp.value = d.url; row.hidden = false; inp.focus(); inp.select();\n    showOk('Copy the link from the field above.');\n  }\n});\n\n/* ---------- Отрисовка общих блоков на странице ---------- */\ndocument.documentElement.dataset.brand = BRAND;\ndocument.querySelectorAll('[data-author]').forEach(el => el.innerHTML = authorHtml());\ndocument.querySelectorAll('[data-greeting]').forEach(el => el.innerHTML = greetingHtml());\ndocument.querySelectorAll('[data-testinfo]').forEach(el => el.innerHTML = testInfoHtml());\ndocument.querySelectorAll('[data-disclaimer]').forEach(el => el.innerHTML = disclaimerHtml());\n/* копирайт внизу каждой страницы сайта */\n(function(){ const w = document.querySelector('.wrap'); if (!w || w.querySelector('.copy')) return;\n  const f = document.createElement('footer'); f.className = 'copy'; f.textContent = '© ' + new Date().getFullYear() + ' Iryna Voznesenskaya. All rights reserved.'; w.appendChild(f); })();\ndocument.querySelectorAll('[data-share]').forEach(el => el.innerHTML = shareHtml(el.dataset.share === 'compact'));\n(function(){\n  const go = document.getElementById('svGo'); if (!go) return;\n  try { (JSON.parse(localStorage.getItem('irinaTestsSurvey') || '[]') || []).forEach(id => { const c = document.getElementById(id); if (c) c.checked = true; }); } catch(e){}\n  go.addEventListener('click', () => {\n    const a = surveyAnswers(), err = document.getElementById('svErr');\n    const miss = !a.heard.length ? 'Please mark how you heard about me.' : !a.interest.length ? 'Please mark what you are interested in.' : '';\n    err.textContent = miss; err.hidden = !miss;\n    if (miss) return;\n    try { localStorage.setItem('irinaTestsSurvey', JSON.stringify([...document.querySelectorAll('input[data-sv]:checked')].map(i => i.id))); } catch(e){}\n    document.querySelector('[data-greeting]').hidden = true;\n    document.getElementById('testStart').hidden = false;\n    window.scrollTo(0, 0);\n  });\n})();\n", "/* =====================================================================\n   Данные и конфиденциальность — общее для всех тестов (с 02.10.2026).\n   - Ответы тестов хранятся только в браузере человека и через 90 дней удаляются сами.\n   - Кнопка «Удалить мои ответы».\n   - Страна спрашивается в мини-опросе (раньше — в анкете перед PDF).\n   - Ссылки на Политику конфиденциальности и Выходные данные в подвале.\n   Тексты на четырёх языках — здесь же (PRIV). Подключается после brand.js, до теста.\n   ===================================================================== */\nconst PAGE_LANG = (typeof LANG !== 'undefined') ? LANG : 'ru';\nconst DATA_DAYS = 90;\n\n/* Страны — коды ISO; названия показываются на языке страницы, в таблицу уходит русское название. */\nconst COUNTRY_TOP = ['CH','DE','AT','FR','IT','ES','NL','BE','GB','PL','CZ','IL','US','CA','UA','RU','BY','KZ'];\nconst COUNTRY_ALL = ['AU','AT','AZ','AL','DZ','AD','AR','AM','AF','BD','BH','BY','BE','BG','BO','BA','BR','GB','HU','VE','VN','GH','DE','HK','GR','GE','DK','DO','EG','IL','IN','ID','JO','IQ','IR','IE','IS','ES','IT','KZ','KH','CA','QA','KE','CY','KG','CN','CO','CR','CU','KW','LV','LB','LT','LI','LU','MU','MY','MV','MT','MA','MX','MD','MC','MN','ME','NP','NG','NL','NZ','NO','AE','OM','PK','PA','PY','PE','PL','PT','RU','RO','SA','MK','RS','SG','SK','SI','US','TJ','TH','TW','TN','TM','TR','UG','UZ','UA','UY','PH','FI','FR','HR','CZ','CL','CH','SE','LK','EC','EE','ZA','KR','JM','JP'];\nconst countryName = (() => { try { const d = new Intl.DisplayNames([PAGE_LANG], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst countryRu = (() => { try { const d = new Intl.DisplayNames(['ru'], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst COUNTRIES = COUNTRY_ALL.map(countryRu);\nconst OTHER_COUNTRY = 'Другая страна';\n\nconst PRIV_ALL = {\n  ru: {\n    countryQ: 'Где ты сейчас живёшь?', countryPick: 'Выбери страну', countryTop: 'Часто выбирают', countryAll: 'Все страны', countryOther: 'Другая страна',\n    countryErr: 'Выбери, пожалуйста, страну, в которой ты сейчас живёшь.',\n    countryNote: 'Страна нужна, чтобы показать в разборе подходящее приглашение и полезные ссылки.',\n    privacy: 'Политика конфиденциальности', impressum: 'Выходные данные', home: 'Главная', allTests: 'Все тесты',\n    onlyYou: 'Твои ответы остаются только у тебя. Я их не вижу.',\n    keepUntil: d => `Твои ответы и разбор хранятся только на этом устройстве, до ${d}. Потом они удалятся сами. Скачай PDF, если хочешь сохранить разбор.`,\n    del: 'Удалить мои ответы', delAsk: 'Удалить все ответы этого теста с этого устройства? Разбор тоже исчезнет. Если хочешь его сохранить, сначала скачай PDF.',\n    delYes: 'Да, удалить', delNo: 'Отмена', delDone: 'Ответы удалены с этого устройства.'\n  },\n  uk: {\n    countryQ: 'Де ти зараз живеш?', countryPick: 'Обери країну', countryTop: 'Часто обирають', countryAll: 'Усі країни', countryOther: 'Інша країна',\n    countryErr: 'Обери, будь ласка, країну, у якій ти зараз живеш.',\n    countryNote: 'Країна потрібна, щоб показати в розборі відповідне запрошення та корисні посилання.',\n    privacy: 'Політика конфіденційності', impressum: 'Вихідні дані', home: 'Головна', allTests: 'Усі тести',\n    onlyYou: 'Твої відповіді залишаються тільки в тебе. Я їх не бачу.',\n    keepUntil: d => `Твої відповіді та розбір зберігаються тільки на цьому пристрої, до ${d}. Потім вони видаляться самі. Завантаж PDF, якщо хочеш зберегти розбір.`,\n    del: 'Видалити мої відповіді', delAsk: 'Видалити всі відповіді цього тесту з цього пристрою? Розбір теж зникне. Якщо хочеш його зберегти, спочатку завантаж PDF.',\n    delYes: 'Так, видалити', delNo: 'Скасувати', delDone: 'Відповіді видалено з цього пристрою.'\n  },\n  de: {\n    countryQ: 'Wo lebst du zurzeit?', countryPick: 'Wähle ein Land', countryTop: 'Häufig gewählt', countryAll: 'Alle Länder', countryOther: 'Anderes Land',\n    countryErr: 'Wähle bitte das Land, in dem du zurzeit lebst.',\n    countryNote: 'Das Land brauche ich, um dir in der Auswertung die passende Einladung und hilfreiche Links zu zeigen.',\n    privacy: 'Datenschutzerklärung', impressum: 'Impressum', home: 'Startseite', allTests: 'Alle Tests',\n    onlyYou: 'Deine Antworten bleiben nur bei dir. Ich sehe sie nicht.',\n    keepUntil: d => `Deine Antworten und die Auswertung sind nur auf diesem Gerät gespeichert, bis ${d}. Danach werden sie automatisch gelöscht. Lade das PDF herunter, wenn du die Auswertung behalten möchtest.`,\n    del: 'Meine Antworten löschen', delAsk: 'Alle Antworten dieses Tests von diesem Gerät löschen? Auch die Auswertung verschwindet. Wenn du sie behalten möchtest, lade zuerst das PDF herunter.',\n    delYes: 'Ja, löschen', delNo: 'Abbrechen', delDone: 'Die Antworten wurden von diesem Gerät gelöscht.'\n  },\n  en: {\n    countryQ: 'Where do you live now?', countryPick: 'Choose a country', countryTop: 'Frequently chosen', countryAll: 'All countries', countryOther: 'Other country',\n    countryErr: 'Please choose the country where you live now.',\n    countryNote: 'I need the country to show you the right invitation and useful links in your results.',\n    privacy: 'Privacy policy', impressum: 'Legal notice', home: 'Home', allTests: 'All tests',\n    onlyYou: 'Your answers stay with you only. I cannot see them.',\n    keepUntil: d => `Your answers and results are stored only on this device, until ${d}. After that they are deleted automatically. Download the PDF if you want to keep your results.`,\n    del: 'Delete my answers', delAsk: 'Delete all answers to this test from this device? Your results will disappear too. If you want to keep them, download the PDF first.',\n    delYes: 'Yes, delete', delNo: 'Cancel', delDone: 'Your answers have been deleted from this device.'\n  }\n};\nconst PRIV = PRIV_ALL[PAGE_LANG] || PRIV_ALL.ru;\n\n/* ---------- 1. Автоудаление ответов через 90 дней ---------- */\n(function purge(){\n  try {\n    const limit = Date.now() - DATA_DAYS * 864e5;\n    for (let i = localStorage.length - 1; i >= 0; i--){\n      const k = localStorage.key(i);\n      if (!k || !/^irinaTests\\./.test(k)) continue;\n      let v = null; try { v = JSON.parse(localStorage.getItem(k) || 'null'); } catch(e){}\n      const t = v && (v.t || v.startedAt);\n      if (!t || t < limit) localStorage.removeItem(k);\n    }\n    localStorage.removeItem('irinaTestsLead');   // прежняя анкета (с e-mail) больше не хранится\n  } catch(e){}\n})();\n\n/* ключ сохранённых ответов текущего теста */\nfunction answersKey(){ return (typeof TEST_META !== 'undefined') ? 'irinaTests.' + TEST_META.id + '.v1' : ''; }\nfunction answersSavedAt(){ try { const v = JSON.parse(localStorage.getItem(answersKey()) || 'null'); return v ? (v.t || v.startedAt || 0) : 0; } catch(e){ return 0; } }\nfunction retentionLine(){\n  const t = answersSavedAt() || Date.now();\n  const d = new Date(t + DATA_DAYS * 864e5).toLocaleDateString(typeof DATE_LOCALE !== 'undefined' ? DATE_LOCALE : 'ru-RU', { day:'2-digit', month:'2-digit', year:'numeric' });\n  return PRIV.keepUntil(d);\n}\n\n/* ---------- 2. Страна в мини-опросе ---------- */\nconst COUNTRY_KEY = 'irinaTestsCountry';\nfunction surveyCountry(){\n  const s = document.getElementById('svCountry');\n  if (s && s.value) return s.value;\n  try { return localStorage.getItem(COUNTRY_KEY) || ''; } catch(e){ return ''; }\n}\n// Тесты раньше брали страну из анкеты (window.__leadCountry). Теперь она всегда берётся из мини-опроса.\ntry { Object.defineProperty(window, '__leadCountry', { configurable: true, get: surveyCountry, set: () => {} }); } catch(e){}\n\nfunction countrySelectHtml(id){\n  return `<select id=\"${id}\"><option value=\"\">${PRIV.countryPick}</option></select>`;\n}\nfunction fillCountrySelect(sel, value){\n  if (!sel || sel.options.length > 1) return;\n  const g1 = document.createElement('optgroup'); g1.label = PRIV.countryTop;\n  COUNTRY_TOP.forEach(c => g1.appendChild(new Option(countryName(c), countryRu(c))));\n  const g2 = document.createElement('optgroup'); g2.label = PRIV.countryAll;\n  COUNTRY_ALL.map(c => [countryName(c), countryRu(c)]).sort((x, y) => x[0].localeCompare(y[0], PAGE_LANG)).forEach(([n, v]) => g2.appendChild(new Option(n, v)));\n  g2.appendChild(new Option(PRIV.countryOther, OTHER_COUNTRY));\n  sel.appendChild(g1); sel.appendChild(g2);\n  if (value && (COUNTRIES.includes(value) || value === OTHER_COUNTRY)) sel.value = value;\n}\n(function surveyCountryField(){\n  const box = document.querySelector('[data-greeting] .surveys'); if (!box || document.getElementById('svCountry')) return;\n  const fs = document.createElement('fieldset'); fs.className = 'survey sv-country';\n  fs.innerHTML = `<legend>${PRIV.countryQ} *</legend>${countrySelectHtml('svCountry')}<p class=\"note\">${PRIV.countryNote}</p>`;\n  box.appendChild(fs);\n  let saved = ''; try { saved = localStorage.getItem(COUNTRY_KEY) || ''; } catch(e){}\n  const sel = fs.querySelector('select'); fillCountrySelect(sel, saved);\n  sel.addEventListener('change', () => { try { localStorage.setItem(COUNTRY_KEY, sel.value); } catch(e){} });\n  // без страны тест не открывается (проверка срабатывает раньше общей кнопки «Перейти к тестированию»)\n  document.addEventListener('click', ev => {\n    const go = ev.target.closest && ev.target.closest('#svGo'); if (!go) return;\n    const a = (typeof surveyAnswers === 'function') ? surveyAnswers() : { heard: [1], interest: [1] };\n    if (!a.heard.length || !a.interest.length) return;          // об этих вопросах скажет общая проверка\n    if (!sel.value){\n      ev.stopPropagation(); ev.preventDefault();\n      const err = document.getElementById('svErr'); if (err){ err.textContent = PRIV.countryErr; err.hidden = false; }\n      sel.focus();\n    } else { try { localStorage.setItem(COUNTRY_KEY, sel.value); } catch(e){} }\n  }, true);\n})();\n\n/* ---------- 3. Удалить мои ответы ---------- */\nfunction deleteAnswersHtml(){\n  if (!answersKey()) return '';\n  return `<div class=\"del-answers\"><button type=\"button\" class=\"linkbtn\" data-del-answers>${PRIV.del}</button>\n    <div class=\"del-ask\" hidden><p>${PRIV.delAsk}</p><div class=\"row\"><button type=\"button\" class=\"btn small\" data-del-yes>${PRIV.delYes}</button><button type=\"button\" class=\"btn ghost small\" data-del-no>${PRIV.delNo}</button></div></div>\n    <p class=\"note del-done\" hidden>${PRIV.delDone}</p></div>`;\n}\ndocument.addEventListener('click', ev => {\n  const b = ev.target.closest && ev.target.closest('[data-del-answers],[data-del-yes],[data-del-no]'); if (!b) return;\n  const box = b.closest('.del-answers'), ask = box.querySelector('.del-ask');\n  if (b.hasAttribute('data-del-answers')){ ask.hidden = !ask.hidden; return; }\n  if (b.hasAttribute('data-del-no')){ ask.hidden = true; return; }\n  try {\n    const pre = 'irinaTests.' + TEST_META.id + '.';\n    for (let i = localStorage.length - 1; i >= 0; i--){ const k = localStorage.key(i); if (k && k.indexOf(pre) === 0) localStorage.removeItem(k); }\n  } catch(e){}\n  ask.hidden = true; box.querySelector('.del-done').hidden = false;\n  setTimeout(() => { location.hash = ''; location.reload(); }, 900);\n});\n\n/* ---------- 4. Подвал: правовые ссылки и удаление ответов ---------- */\nfunction legalUrl(page){\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  return root + page + '/';\n}\nfunction privacyLinksHtml(){\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  return `<a href=\"${root}\">${PRIV.home}</a> · <a href=\"${root}testy/\">${PRIV.allTests}</a> · <a href=\"${legalUrl('privacy')}\">${PRIV.privacy}</a> · <a href=\"${legalUrl('impressum')}\">${PRIV.impressum}</a>`;\n}\n(function footer(){\n  const f = document.querySelector('.wrap .copy'); if (!f || f.querySelector('.legal-links')) return;\n  const p = document.createElement('span'); p.className = 'legal-links'; p.innerHTML = privacyLinksHtml();\n  f.appendChild(document.createElement('br')); f.appendChild(p);\n  if (answersKey() && document.getElementById('intro')){\n    const d = document.createElement('div'); d.innerHTML = deleteAnswersHtml(); f.appendChild(d.firstElementChild);\n  }\n})();\n/* строка «Твои ответы остаются только у тебя» на стартовой странице, рядом с кнопкой начала */\n(function startNote(){\n  const host = document.querySelector('#testStart [data-share=\"compact\"]'); if (!host || document.querySelector('.only-you')) return;\n  const p = document.createElement('p'); p.className = 'note only-you';\n  p.innerHTML = `${PRIV.onlyYou} <a href=\"${legalUrl('privacy')}\">${PRIV.privacy}</a>`;\n  host.parentNode.insertBefore(p, host);\n})();\n\n/* ---------- 6. Общая шапка сайта на каждой странице (тесты, «Тесты», правовые) — вернуться можно откуда угодно ---------- */\n(function siteHeader(){\n  if (document.querySelector('.sitebar')) return;\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  const T = {\n    ru: { sub: 'коуч ICF · Цюрих', name: 'Ирина Вознесенская', nav: ['С чего начать', 'Твой путь', 'Обо мне', 'Тесты', 'Контакт'], cta: 'Знакомство' },\n    uk: { sub: 'коуч ICF · Цюрих', name: 'Ірина Вознесенська', nav: ['З чого почати', 'Твій шлях', 'Про мене', 'Тести', 'Контакт'], cta: 'Знайомство' },\n    de: { sub: 'ICF-Coach · Zürich', name: 'Iryna Voznesenskaya', nav: ['Wo anfangen', 'Dein Weg', 'Über mich', 'Tests', 'Kontakt'], cta: 'Kennenlernen' },\n    en: { sub: 'ICF coach · Zurich', name: 'Iryna Voznesenskaya', nav: ['Where to start', 'Your path', 'About me', 'Tests', 'Contact'], cta: 'Intro call' }\n  }[PAGE_LANG] || {};\n  const L = T.nav ? T : { sub: 'коуч ICF · Цюрих', name: 'Ирина Вознесенская', nav: ['С чего начать', 'Твой путь', 'Обо мне', 'Тесты', 'Контакт'], cta: 'Знакомство' };\n  const hrefs = [root + '#doors', root + 'put/', root + '#about', root + 'testy/', root + '#contact'];\n  const here = location.pathname.replace(/\\/+$/, '').split('/').pop();\n  const h = document.createElement('header'); h.className = 'sitebar';\n  h.innerHTML = `<div class=\"sitebar-in\">\n    <a class=\"sb-mark\" href=\"${root}\"><span class=\"sb-mono av\">${typeof AVATAR_SVG !== \"undefined\" ? AVATAR_SVG : \"ИВ\"}</span><span><b>${L.name}</b><small>${L.sub}</small></span></a>\n    <nav class=\"sb-nav\" aria-label=\"Menu\">${L.nav.map((t, i) => `<a href=\"${hrefs[i]}\"${i === 3 && here === 'testy' ? ' aria-current=\"page\"' : ''}>${t}</a>`).join('')}</nav>\n    <a class=\"sb-cta\" href=\"https://t.me/IrynaNeuroCoach\" target=\"_blank\" rel=\"noopener\">${L.cta}</a></div>`;\n  document.body.insertBefore(h, document.body.firstChild);\n})();\n", "/* ---------- схемы «Компаса адаптации» ----------\n   Простые линейные схемы на фоне страницы: тонкие линии, один акцентный цвет, без картинок. */\nconst LN = { ink:'#3A322B', muted:'#9A8D7E', line:'#D8CDBE', acc:'#8A5A3B', soft:'#EFE6D8' };\nconst sf = (x, y, t, o = {}) => `<text x=\"${x}\" y=\"${y}\" text-anchor=\"${o.a || 'middle'}\" font-family=\"${o.serif ? 'Forum, Georgia, serif' : 'Manrope, sans-serif'}\" font-size=\"${o.s || 12}\" font-weight=\"${o.w || 400}\" fill=\"${o.c || LN.ink}\" ${o.ls ? `letter-spacing=\"${o.ls}\"` : ''}>${t}</text>`;\n\n/* Обложка: тонкий компас */\nfunction compassSVG(){\n  const c = 70;\n  let s = `<svg viewBox=\"0 0 140 140\" role=\"img\" aria-label=\"Compass\" width=\"150\" height=\"150\">\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"60\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.2\"/>\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"52\" fill=\"none\" stroke=\"${LN.line}\" stroke-width=\"1\"/>`;\n  for (let k = 0; k < 24; k++){ const a = k * Math.PI / 12, r1 = k % 6 === 0 ? 44 : 49; s += `<line x1=\"${(c + r1 * Math.cos(a)).toFixed(1)}\" y1=\"${(c + r1 * Math.sin(a)).toFixed(1)}\" x2=\"${(c + 52 * Math.cos(a)).toFixed(1)}\" y2=\"${(c + 52 * Math.sin(a)).toFixed(1)}\" stroke=\"${LN.ink}\" stroke-width=\"${k % 6 === 0 ? 1.2 : .7}\"/>`; }\n  s += `<path d=\"M${c} ${c - 38} L${c + 7} ${c} L${c} ${c + 38} L${c - 7} ${c}Z\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.1\"/>\n    <path d=\"M${c} ${c - 38} L${c + 7} ${c} L${c - 7} ${c}Z\" fill=\"${LN.acc}\"/>\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"3\" fill=\"${LN.ink}\"/>` + sf(c, 20, 'N', { serif:true, s:12 });\n  return s + '</svg>';\n}\n\n/* Две культуры: схема 2 × 2 и точка — где человек сейчас */\nfunction shoresSVG(own, neu){\n  const W = 520, H = 420, x0 = 90, y0 = 30, S = 340;               // поле S×S\n  const px = x0 + S * neu / 20, py = y0 + S * (1 - own / 20);\n  const q = [['Your own island', 0, 0], ['A bridge between worlds', 1, 0], ['Between two shores', 0, 1], ['A new life from scratch', 1, 1]];\n  const mine = (own >= 10 ? 0 : 1) * 2 + (neu >= 10 ? 1 : 0);\n  // цвета по спирали: своя культура — фиолетовый, мост — бирюзовый, между берегами — бежевый, новая культура — жёлтый\n  const QF = ['#EDEBF8', '#E1F5F6', '#F3F1EC', '#F9F5DE'], QL = ['#6A5FB8', '#2894A0', '#8E8470', '#A99A2E'];\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Diagram: your own culture and the new one\">`;\n  q.forEach(([t, cx, cy], i) => {\n    const x = x0 + cx * S / 2, y = y0 + cy * S / 2;\n    s += `<rect x=\"${x}\" y=\"${y}\" width=\"${S / 2}\" height=\"${S / 2}\" fill=\"${QF[i]}\" opacity=\"${i === mine ? 1 : .35}\"/>`;\n    const words = t.split(' '), mid = Math.ceil(words.length / 2);\n    const l1 = words.length > 2 ? words.slice(0, mid).join(' ') : t, l2 = words.length > 2 ? words.slice(mid).join(' ') : '';\n    s += sf(x + S / 4, y + S / 4 - (l2 ? 4 : -4), l1, { serif:true, s:19, c: i === mine ? QL[i] : LN.muted });\n    if (l2) s += sf(x + S / 4, y + S / 4 + 20, l2, { serif:true, s:19, c: i === mine ? QL[i] : LN.muted });\n  });\n  s += `<rect x=\"${x0}\" y=\"${y0}\" width=\"${S}\" height=\"${S}\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1\"/>\n    <line x1=\"${x0 + S / 2}\" y1=\"${y0}\" x2=\"${x0 + S / 2}\" y2=\"${y0 + S}\" stroke=\"${LN.line}\" stroke-dasharray=\"3 4\"/>\n    <line x1=\"${x0}\" y1=\"${y0 + S / 2}\" x2=\"${x0 + S}\" y2=\"${y0 + S / 2}\" stroke=\"${LN.line}\" stroke-dasharray=\"3 4\"/>`;\n  [0, 10, 20].forEach(v => {\n    s += sf(x0 + S * v / 20, y0 + S + 18, v, { c:LN.muted, s:11 }) + sf(x0 - 10, y0 + S * (1 - v / 20) + 4, v, { a:'end', c:LN.muted, s:11 });\n  });\n  s += sf(x0 + S / 2, y0 + S + 42, 'connection to the new culture →', { c:LN.muted, s:12, ls:'.5' });\n  s += `<text transform=\"translate(${x0 - 40} ${y0 + S / 2}) rotate(-90)\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-size=\"12\" letter-spacing=\".5\" fill=\"${LN.muted}\">connection to your own culture →</text>`;\n  s += `<line x1=\"${px}\" y1=\"${y0 + S}\" x2=\"${px}\" y2=\"${py}\" stroke=\"${QL[mine]}\" stroke-dasharray=\"2 3\"/><line x1=\"${x0}\" y1=\"${py}\" x2=\"${px}\" y2=\"${py}\" stroke=\"${QL[mine]}\" stroke-dasharray=\"2 3\"/>\n    <circle cx=\"${px}\" cy=\"${py}\" r=\"9\" fill=\"${QL[mine]}\"/><circle cx=\"${px}\" cy=\"${py}\" r=\"15\" fill=\"none\" stroke=\"${QL[mine]}\" stroke-width=\"1\"/>`;\n  s += sf(px + (px > x0 + S - 60 ? -22 : 22), py - 16, 'you are here', { a: px > x0 + S - 60 ? 'end' : 'start', c:QL[mine], w:700, s:15 });\n  return s + '</svg>';\n}\n\n/* Шесть сфер: дорожки 0–20, каждая сфера в своей рамке */\nfunction flowerSVG(sc){\n  const W = 560, rowH = 56, H = 30 + rowH * sc.length, x0 = 168, x1 = 486;\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Six areas\">`;\n  const max = Math.max(...sc), min = Math.min(...sc);\n  sc.forEach((v, k) => {\n    const y = 30 + k * rowH, x = x0 + (x1 - x0) * v / 20, hi = v === max || v === min;\n    const col = css(AC[k]), soft = css(AS[k]);\n    s += `<rect x=\"4\" y=\"${y - 22}\" width=\"${W - 8}\" height=\"44\" rx=\"10\" fill=\"${soft}\" stroke=\"${col}\" stroke-width=\"1.2\"/>`;\n    s += `<g transform=\"translate(20 ${y - 12})\">${aIcon(k).replace(/^<svg[^>]*>/, '').replace(/<\\/svg>$/, '')}</g>`;\n    s += sf(54, y + 6, AREAS[k].short, { a:'start', serif:true, s:19, c: col });\n    [5, 10, 15].forEach(t => { const tx = x0 + (x1 - x0) * t / 20; s += `<line x1=\"${tx}\" y1=\"${y - 7}\" x2=\"${tx}\" y2=\"${y + 7}\" stroke=\"${col}\" stroke-width=\".8\" opacity=\".35\"/>`; });\n    s += `<line x1=\"${x0}\" y1=\"${y}\" x2=\"${x1}\" y2=\"${y}\" stroke=\"#fff\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <line x1=\"${x0}\" y1=\"${y}\" x2=\"${x}\" y2=\"${y}\" stroke=\"${col}\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <circle cx=\"${x}\" cy=\"${y}\" r=\"${hi ? 9 : 7}\" fill=\"${col}\" stroke=\"#fff\" stroke-width=\"2\"/>`;\n    s += sf(x1 + 18, y + 6, `${v}/20`, { a:'start', s:14, w:700, c: col });\n  });\n  [0, 10, 20].forEach(v => { const x = x0 + (x1 - x0) * v / 20; s += sf(x, H - 2, v, { c:LN.muted, s:10 }); });\n  return s + '</svg>';\n}\n\n/* Путь адаптации: линия с этапами */\nfunction journeySVG(stage){\n  const W = 560, H = 190;\n  const P = [[50, 60], [200, 140], [360, 100], [510, 40]], names = ['Discovery','Struggles','Footholds','At home'];\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Path of adaptation\">`;\n  s += `<path d=\"M50 60 C110 60 140 140 200 140 S310 100 360 100 S460 40 510 40\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.4\"/>`;\n  if (stage === 4) s += `<path d=\"M360 100 C390 150 300 175 280 140 C265 112 320 95 360 100\" fill=\"none\" stroke=\"${LN.acc}\" stroke-width=\"1.4\" stroke-dasharray=\"4 4\"/>`;\n  P.forEach(([x, y], i) => {\n    const on = i === stage;\n    s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"${on ? 9 : 6}\" fill=\"${on ? LN.acc : '#fff'}\" stroke=\"${on ? LN.acc : LN.ink}\" stroke-width=\"1.4\"/>`;\n    s += sf(x, y + (i === 1 ? 30 : 28), names[i], { serif:true, s:16, c: on ? LN.acc : LN.ink });\n  });\n  const at = stage === 4 ? [300, 165] : P[stage];\n  s += sf(at[0], at[1] - 18, stage === 4 ? 'new round · you are here' : 'you are here', { s:12, w:700, c:LN.acc, ls:'.4' });\n  return s + '</svg>';\n}\n", "/* =====================================================================\n   «Компас адаптации» — коучинговый самотест про адаптацию в эмиграции.\n   ===================================================================== */\nconst AREAS = [\n  { name: 'Language and communication', short: 'Language',\n    items: ['I speak the local language in everyday situations, even with mistakes.',\n            'I learn the language: classes, an app, books, TV series.',\n            'I start conversations with local people myself, not just answer their questions.',\n            'I read letters, websites and notices in the local language without a translator, or with very little help.',\n            'I ask again and ask for an explanation when I don’t understand something, instead of staying silent.'],\n    lv: ['Language is still quiet for now. That is normal: language is one of the biggest loads after moving abroad, and many people need time to start speaking without fear. Every small conversation is already a step.',\n         'Language is in progress: you already use it, but perhaps still with tension or only in familiar situations. What matters now is regularity, not perfection.',\n         'Language is your anchor. You speak, you learn and you are not afraid of mistakes. This opens the door to everything else: work, people and the feeling that you are not a guest here.'],\n    recs: ['Choose one situation a week where you speak only the local language: a café, a shop, your neighbours.',\n           '15 minutes of language every day is better than two hours once a week. A series, a podcast or an app will do.',\n           'Find a language partner or a conversation club: everyone there learns and makes mistakes together.'],\n    focus: 'speak the new language more boldly' },\n  { name: 'Daily life and the system', short: 'Everyday',\n    items: ['I calmly deal with documents, letters, insurance and bills.',\n            'I know where to turn if something happens: a doctor, the local authorities, the insurance company, a lawyer.',\n            'I use local services: transport, the bank, the post office, apps.',\n            'I understand local rules and unwritten norms and follow them without inner protest.',\n            'I make my home cosy: things, order and little details I like.'],\n    lv: ['Daily life and the system are still not easy. The letters, documents and rules of a new country can be frightening and take a lot of energy. Almost everyone who moves faces this.',\n         'You already find your way in daily life, but some things still cause anxiety or take a lot of energy. A little more experience, and the system will become clearer.',\n         'Daily life and the system are your anchor. You know how things work and act with confidence. This frees up energy for what really matters.'],\n    recs: ['Keep one folder for all your documents and letters, and go through it once a week at the same time.',\n           'Make a “who to call if…” list: doctor, insurance, local authorities, emergency services.',\n           'Ask locals or experienced emigrants about the unwritten rules. Much is simpler than it seems.'],\n    focus: 'feel more confident in the new system' },\n  { name: 'Work and fulfilment', short: 'Work',\n    items: ['I take steps towards work or a calling that suits me: studies, a CV, projects, interviews.',\n            'I use my skills and experience, not just do whatever comes along.',\n            'I find out how the job market and my profession work in the new country.',\n            'I finish what I start and see the results of my efforts.',\n            'I talk about my skills and achievements out loud, without playing them down.'],\n    lv: ['Work and fulfilment are quiet right now. After a move, many people temporarily lose their professional footing, and this is one of the most sensitive topics. It is important to remember: your experience has not disappeared.',\n         'You are moving towards your own work, but perhaps you are not yet where you want to be, or you are not using everything you can do. This is an in-between stage, and there is a way through it.',\n         'Work and fulfilment are your anchor. You use your strengths and see results. This gives you confidence and the feeling that you are in the right place.'],\n    recs: ['Write down 10 of your skills and achievements, including ones from your past life. Reread them before important conversations.',\n           'Talk to two people who already work in your field in this country. Ask them how they started.',\n           'Set one small goal for the month: a course, a CV, a project or a meeting.'],\n    focus: 'find work where you can truly unfold' },\n  { name: 'People and connections', short: 'People',\n    items: ['I meet friends or acquaintances in the new country in person.',\n            'I spend time with local people, not only with Russian speakers.',\n            'I keep in touch with loved ones back home in a way that feels warm, not heavy.',\n            'I take part in things together with others: courses, clubs, volunteering, sport, parents’ chats.',\n            'I share what I am going through with at least one person and receive support.'],\n    lv: ['Connections with people are quiet right now. Loneliness is a frequent companion of a new start abroad, even when your family is close by. New ties are built slowly, and that says nothing bad about you.',\n         'There are people around you, but perhaps there is not enough depth or variety: only people from your own community, or only through work. This is an easy place to take the next step.',\n         'People and connections are your anchor. You have people to share joys and difficulties with, in both your old and your new life. This is one of the strongest protections against stress.'],\n    recs: ['Choose one regular activity with other people: sport, a choir, a course, volunteering. Regular contact grows into friendship.',\n           'Be the first to invite someone for coffee. Many people are also waiting to be asked.',\n           'Agree on a regular time to call your loved ones back home, so the connection feels warm rather than anxious.'],\n    focus: 'find your people in the new country' },\n  { name: 'Energy: body and rest', short: 'Energy',\n    items: ['I get enough sleep and wake up full of energy.',\n            'I move: walks, sport, nature.',\n            'I do things just for pleasure, with no use or purpose.',\n            'I notice when I am tired and let myself rest instead of “pushing through”.',\n            'I get out to beautiful places in the new country and enjoy them.'],\n    lv: ['Your energy is low right now. Adaptation takes a great deal of energy, and the body is often the first to signal tiredness. This is not weakness, but a sign that you need care.',\n         'You take care of yourself, but not always. When things get hard, rest and pleasure are the first to go. It is worth making them part of your schedule.',\n         'Body and rest are your anchor. You know how to rest, move and enjoy life. This is fuel for all the other areas.'],\n    recs: ['Add one small pleasure with no purpose to every day: coffee on the balcony, music, a walk.',\n           'Move for at least 20 minutes a day. A walk counts too.',\n           'Once a week, discover a new beautiful place in the country. This is how the new country slowly becomes yours.'],\n    focus: 'get your energy and joy back' },\n  { name: 'Self and meaning', short: 'Meaning',\n    items: ['I do what matters to me personally, not only what I “have to” do.',\n            'I picture what I want my life here to look like in a year, and take steps towards it.',\n            'I notice what has grown and changed in me thanks to the move.',\n            'I make decisions based on my own values, not on other people’s expectations.',\n            'I allow myself to be myself: I speak, dress and rest the way I like.'],\n    lv: ['Your sense of self and meaning is quiet right now. After a move, many people feel they have lost part of themselves: former roles, status, familiar supports. This is a time when you can piece yourself together anew.',\n         'You are searching for yourself in your new life and already finding supports. Sometimes the feeling comes back that you are living a life that is not your own. This is part of the journey.',\n         'You remain yourself and live by your own values. The move has been not only a challenge, but also growth. This is the deepest anchor of adaptation.'],\n    recs: ['Every evening, write down one thing you did today that mattered to you personally.',\n           'Describe what you want your life here to look like in a year. Choose one step towards it.',\n           'Remember what gave you strength before the move. What of it could you bring back here?'],\n    focus: 'find yourself and your place in the new world' }\n];\nconst CULT = [\n  { name: 'Connection to your own culture',\n    items: ['I speak my native language at home or with friends.',\n            'I cook familiar food and celebrate the holidays and traditions of my culture.',\n            'I read, watch or listen to something in my native language.',\n            'I spend time with people from my culture in the new country.',\n            'I pass on something important from my culture to my children or loved ones.'] },\n  { name: 'Connection to the new culture',\n    items: ['I try local food, holidays and customs.',\n            'I watch local news and films and listen to local music.',\n            'I go to local events: markets, festivals, gatherings.',\n            'I spend time with local people outside work.',\n            'I learn about the history and character of the country I live in.'] }\n];\nconst YEARS = ['less than 6 months','6–12 months','1–3 years','3–5 years','more than 5 years'];\nconst STAGES = [\n  { phrase: 'Everything is new and exciting, there is so much to discover.', name: 'Time of discovery',\n    text: 'Everything is new and inspiring. This is a wonderful time to lay foundations: language, new acquaintances, habits. Over time, inspiration may give way to tiredness, and that is a normal part of the journey.' },\n  { phrase: 'It has become harder: lots of tiredness and irritation, I want to go home.', name: 'Time of struggle',\n    text: 'Things may be hard right now: tiredness, irritation, homesickness. This is the most common and most natural stage of adaptation. It passes, especially when there is support around you.' },\n  { phrase: 'I am gradually settling in and finding my own ways and supports.', name: 'Time of footholds',\n    text: 'You are gradually finding your own ways of living here. There are still difficulties, but there are more and more supports. Now is a good time to strengthen what already works.' },\n  { phrase: 'This is my home, I can be myself here.', name: 'At home',\n    text: 'This is your home, and you can be yourself. This is the result of a long journey. Now you can think not only about how to cope, but also about what you want.' },\n  { phrase: 'After a calm period, things have become hard again.', name: 'A new round',\n    text: 'After a period of stability, things have become hard again. This happens: adaptation does not run in a straight line, but in waves. A new wave is not a step backwards, but an invitation to the next step.' }\n];\nconst STRATEGY = {\n  both: ['A bridge between worlds', 'You lovingly keep your own culture and at the same time open up to the new one. In the psychology of adaptation this is called integration, and it is the most stable path: you have both roots and wings. It is important to keep holding on to both shores without wearing yourself out from the double load.'],\n  newOnly: ['A new life from scratch', 'You are actively entering the new culture, while your connection to your own has grown quieter. This helps you settle in quickly. Sometimes, though, part of your support goes along with the past. Think about what from your own culture you would like to keep for yourself and your loved ones.'],\n  ownOnly: ['Your own island', 'You cherish your own culture, language and habits, while the new country still stays a little to the side. This gives you safety and warmth. The next step is to gradually build bridges to the new culture without losing what is yours.'],\n  none: ['Between two shores', 'Right now your connection to both your own culture and the new one is quiet. This often happens in times of tiredness or right after a move, when you only have energy for the essentials. It is not forever. Even small steps towards people and traditions, both your own and new ones, help you feel supported.']\n};\nconst LV_NAME = ['still quiet','in progress','your anchor'];\nconst KEEP = 'This area is already working for you. Keep doing what you are doing, and lean on it when things get hard.';\nconst LABELS = ['never','1–2 times','sometimes','often','almost always'];\nconst AC = ['--a0','--a1','--a2','--a3','--a4','--a5'];\nconst AS = ['--a0s','--a1s','--a2s','--a3s','--a4s','--a5s'];\n\n/* ---------- состояние ---------- */\n// шаги: 0 — о переезде; 1–3 — по две сферы; 4 — две культуры\nlet step = 0, ctx = { years: null, stage: null }, ans = { areas: AREAS.map(() => Array(5).fill(null)), cult: CULT.map(() => Array(5).fill(null)) };\nlet myName = '', last = null;\nconst $ = id => document.getElementById(id);\nconst css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();\nconst sum = a => a.reduce((x, y) => x + y, 0);\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst lvl = s => s <= 7 ? 0 : s <= 13 ? 1 : 2;\nconst TOTAL = 5 * 6 + 10 + 2;\n\n$('startBtn').addEventListener('click', () => {\n  myName = $('nameMe').value.trim();\n  resetInvite(); window.__leadCountry = '';\n  step = 0; ctx = { years: null, stage: null };\n  ans = { areas: AREAS.map(() => Array(5).fill(null)), cult: CULT.map(() => Array(5).fill(null)) };\n  $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0, 0);\n});\n\nfunction choiceGroup(title, opts, key){\n  const wrap = document.createElement('div'); wrap.className = 'q';\n  wrap.innerHTML = `<p>${title}</p><div class=\"choices1\" role=\"group\"></div>`;\n  const g = wrap.querySelector('.choices1');\n  opts.forEach((o, i) => {\n    const b = document.createElement('button'); b.className = 'opt1'; b.id = `c-${key}-${i}`; b.textContent = o;\n    b.setAttribute('aria-pressed', ctx[key] === i ? 'true' : 'false');\n    b.addEventListener('click', () => { ctx[key] = i; g.querySelectorAll('.opt1').forEach((x, n) => x.setAttribute('aria-pressed', n === i ? 'true' : 'false')); update(); });\n    g.appendChild(b);\n  });\n  return wrap;\n}\nfunction scaleItem(text, num, arr, i, idPrefix){\n  const q = document.createElement('div'); q.className = 'q';\n  q.innerHTML = `<p><span class=\"n\">${num}.</span>${text}</p><div class=\"opts\" role=\"group\" aria-label=\"Rating\"></div>`;\n  const opts = q.querySelector('.opts');\n  for (let v = 0; v <= 4; v++){\n    const o = document.createElement('button'); o.className = 'opt'; o.id = `${idPrefix}-${i}-${v}`;\n    o.setAttribute('aria-pressed', arr[i] === v ? 'true' : 'false');\n    o.innerHTML = `<b>${v}</b><small>${LABELS[v]}</small>`;\n    o.addEventListener('click', () => { arr[i] = v; opts.querySelectorAll('.opt').forEach((x, n) => x.setAttribute('aria-pressed', n === v ? 'true' : 'false')); update(); });\n    opts.appendChild(o);\n  }\n  return q;\n}\nfunction renderStep(){\n  const list = $('qlist'); list.innerHTML = '';\n  $('stepLabel').textContent = `Step ${step + 1} of 5`;\n  if (step === 0){\n    document.documentElement.style.setProperty('--accent', 'var(--plum)');\n    $('partTag').textContent = 'About your move';\n    $('roleTitle').textContent = 'Where you are now'; $('roleTitle').style.color = 'var(--plum)';\n    $('roleSub').textContent = 'Two short questions to make your report more accurate.';\n    list.appendChild(choiceGroup('How long have you been living in the new country?', YEARS, 'years'));\n    list.appendChild(choiceGroup('Which phrase feels closest right now?', STAGES.map(s => s.phrase), 'stage'));\n  } else if (step <= 3){\n    const pair = [(step - 1) * 2, (step - 1) * 2 + 1];\n    document.documentElement.style.setProperty('--accent', `var(${AC[pair[0]]})`);\n    $('partTag').textContent = 'Areas of your new life · over the last 4 weeks';\n    $('roleTitle').textContent = `${AREAS[pair[0]].name} · ${AREAS[pair[1]].name}`; $('roleTitle').style.color = `var(${AC[pair[0]]})`;\n    $('roleSub').textContent = 'Mark how often this really happened.';\n    let n = (step - 1) * 10;\n    pair.forEach(a => {\n      const h = document.createElement('div'); h.className = 'qhead'; h.style.color = `var(${AC[a]})`; h.textContent = AREAS[a].name; list.appendChild(h);\n      AREAS[a].items.forEach((t, i) => list.appendChild(scaleItem(t, ++n, ans.areas[a], i, `a${a}`)));\n    });\n  } else {\n    document.documentElement.style.setProperty('--accent', 'var(--plum)');\n    $('partTag').textContent = 'Two cultures · over the last 4 weeks';\n    $('roleTitle').textContent = 'Your culture and the new one'; $('roleTitle').style.color = 'var(--plum)';\n    $('roleSub').textContent = 'There is no right balance here. What matters is simply to see how it is for you now.';\n    let n = 30;\n    CULT.forEach((c, k) => {\n      const h = document.createElement('div'); h.className = 'qhead'; h.textContent = c.name; list.appendChild(h);\n      c.items.forEach((t, i) => list.appendChild(scaleItem(t, ++n, ans.cult[k], i, `c${k}`)));\n    });\n  }\n  $('next').textContent = step === 4 ? 'Show my report' : 'Next';\n  update();\n}\nfunction doneCount(){\n  return (ctx.years !== null) + (ctx.stage !== null) + ans.areas.flat().filter(v => v !== null).length + ans.cult.flat().filter(v => v !== null).length;\n}\nfunction stepComplete(){\n  if (step === 0) return ctx.years !== null && ctx.stage !== null;\n  if (step <= 3) return [(step - 1) * 2, (step - 1) * 2 + 1].every(a => ans.areas[a].every(v => v !== null));\n  return ans.cult.every(c => c.every(v => v !== null));\n}\nfunction update(){\n  const d = doneCount();\n  $('countLabel').textContent = `${d} of ${TOTAL}`;\n  $('prog').style.width = (d / TOTAL * 100) + '%';\n  $('next').disabled = !stepComplete();\n}\n$('next').addEventListener('click', () => { if (step < 4){ step++; renderStep(); window.scrollTo(0, 0); } else showResult(); });\n$('back').addEventListener('click', () => {\n  if (step > 0){ step--; renderStep(); window.scrollTo(0, 0); }\n  else { $('quiz').hidden = true; $('intro').hidden = false; }\n});\n\n/* ---------- картинки ---------- */\nfunction aIcon(k){   // значки — из общей библиотеки assets/icons.js\n  return ico(['speech', 'home', 'workshop', 'people', 'cup', 'compass'][k], ['#C25468','#3F6FBF','#C97E52','#4E9A70','#8E8470','#2894A0'][k], ['#EEA9B3','#A6C4F0','#F2C6A8','#B0DCC0','#E2DCD0','#9ADDE0'][k]);\n}\nconst bar = (v, max, color) => `<div class=\"bar\"><i style=\"width:${v / max * 100}%;background:${color}\"></i></div>`;\n\n/* ---------- разбор ---------- */\nfunction compute(){\n  const sc = ans.areas.map(sum);\n  const own = sum(ans.cult[0]), neu = sum(ans.cult[1]);\n  const key = own >= 10 && neu >= 10 ? 'both' : neu >= 10 ? 'newOnly' : own >= 10 ? 'ownOnly' : 'none';\n  const idx = Math.round(sum(sc) / 120 * 100);\n  const strong = sc.indexOf(Math.max(...sc)), weak = sc.lastIndexOf(Math.min(...sc));\n  return { sc, own, neu, key, idx, strong, weak };\n}\nfunction buildBlocks(){\n  const r = compute(); last = r;\n  const N = esc(myName);\n  const [sName, sText] = STRATEGY[r.key];\n  const st = STAGES[ctx.stage];\n  const date = new Date().toLocaleDateString(DATE_LOCALE, { day: 'numeric', month: 'long', year: 'numeric' });\n  const B = [];\n\n  B.push({ html: `<div class=\"blk hero k-hero\"><div class=\"split\">\n      <div class=\"stack\" style=\"gap:10px\"><div class=\"eyebrow\">Adaptation Compass · report</div>\n        ${N ? `<div class=\"names\">${N}</div>` : ''}\n        <h1>${sName}</h1>\n        <p class=\"note\">${date} · in the country for ${YEARS[ctx.years]} · stage: ${st.name.toLowerCase()}</p></div>\n      <div class=\"fig\" style=\"flex:0 0 150px;width:150px\">${compassSVG()}</div></div></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Two cultures</div><h2>Your path between two cultures</h2>\n      <div style=\"max-width:460px;width:100%;margin:0 auto\">${shoresSVG(r.own, r.neu)}</div>\n      <h3>${sName}</h3><p>${sText}</p>\n      <p class=\"note\">Your own culture: <b>${r.own} of 20</b> · new culture: <b>${r.neu} of 20</b>. A connection counts as strong from 10 points.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Stage of adaptation</div><h2>${st.name}</h2>${journeySVG(ctx.stage)}<p>${st.text}</p>\n      <p class=\"note\">The stages are described according to the classic model of adapting to a new culture (the U-curve). Everyone has their own pace, and stages can repeat.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Six areas</div><h2>Six areas of your new life</h2>${flowerSVG(r.sc)}\n      <p class=\"note\">Each area scores from 0 to 20 points. Overall adaptation index: <b>${r.idx}%</b>. This is not a grade, but a starting point.</p></div>` });\n  B.push({ html: testInfoHtml() });\n\n  B.push({ newPage: true, html: `<div class=\"blk plain\"><div class=\"eyebrow\">Area by area</div><h2>Where your anchors are and where it is still quiet</h2>\n      <p>Your strongest area right now is <b style=\"color:var(${AC[r.strong]})\">${AREAS[r.strong].name.toLowerCase()}</b>. You can lean on it. The quietest is <b style=\"color:var(${AC[r.weak]})\">${AREAS[r.weak].name.toLowerCase()}</b>. It is a good place to start.</p></div>` });\n  r.sc.forEach((s, k) => {\n    const l = lvl(s);\n    const recs = l === 2 ? `<p class=\"recs\" style=\"padding-left:14px\">${KEEP}</p>`\n      : `<div class=\"recs-t\">What will help</div><ul class=\"recs\">${AREAS[k].recs.map(x => `<li>${x}</li>`).join('')}</ul>`;\n    B.push({ html: `<div class=\"blk role-blk\" style=\"--c:var(${AC[k]});--cs:var(${AS[k]})\">\n      <div class=\"role-head\"><div class=\"ico\">${aIcon(k)}</div><h3>${AREAS[k].name}</h3>\n        <span class=\"pill\" style=\"background:var(${AC[k]})\">${LV_NAME[l]}</span><span class=\"sc\">${s} / 20</span></div>\n      <p>${AREAS[k].lv[l]}</p>${recs}</div>` });\n  });\n\n  const low = AREAS[r.weak].items.map((t, i) => [t, ans.areas[r.weak][i]]).sort((a, b) => a[1] - b[1]).slice(0, 2);\n  const ritual = ['Once a week, do something for the first time in the new country: a place, a dish, an event.',\n                  'Once a week, rest for real: no chores, no phone, just what fills you up.',\n                  'Once a week, note what has already worked out. Small wins count too.',\n                  'Once a month, think about what you want next here, and choose one step.',\n                  'Once a week, do something kind for yourself and talk to someone who supports you.'][ctx.stage];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">4-week plan</div><h2>Small steps that change your life</h2>\n    <div class=\"steps\">\n      <div><span class=\"num\">1</span><div><b>Your area of growth: ${AREAS[r.weak].name.toLowerCase()}</b><p>Choose one action and do it at least twice a week:</p>\n        <ul class=\"clean\" style=\"margin-top:6px\">${low.map(([t]) => `<li>${t.replace(/^I /, '').replace(/^./, c => c.toUpperCase())}</li>`).join('')}</ul></div></div>\n      <div><span class=\"num\">2</span><div><b>Your anchor: ${AREAS[r.strong].name.toLowerCase()}</b><p>When things get hard, lean on this area. Notice what is working for you in it, and let it support the others.</p></div></div>\n      <div><span class=\"num\">3</span><div><b>Ritual for the “${st.name.toLowerCase()}” stage</b><p>${ritual}</p></div></div>\n      <div><span class=\"num\">4</span><div><b>In 4 weeks</b><p>Take the test again and see how your compass has changed.</p></div></div>\n    </div></div>` });\n  B.push({ html: `<div class=\"blk\"><h2>Questions to reflect on</h2><p class=\"note\">Take your time with the answers. You can write them down or simply stay with them for a while.</p>\n    <ul class=\"clean\">\n      <li>When you are in your place, you are like what? What is that like?</li>\n      <li>What is already helping you in the new country? What else could help?</li>\n      <li>What would you like for yourself in this country?</li>\n      <li>What from your previous life do you want to keep, and what could you gently let go of?</li>\n      <li>Who or what supports you here?</li>\n      <li>What small step this week would bring you closer to the feeling “I am at home”?</li>\n    </ul></div>` });\n\n  /* Swiss Guide (@swisscompass_bot): показываем только тем, кто живёт в Швейцарии (или страна ещё не указана) */\n  { const ctry = window.__leadCountry || ((typeof loadLead === 'function' && loadLead()) || {}).country || '';\n    if (!ctry || ctry === 'Швейцария') {\n      const inCH = ctry === 'Швейцария';\n      B.push({ html: `<div class=\"blk swiss-guide\"><div class=\"eyebrow\">${inCH ? 'For life in Switzerland' : 'If you live in Switzerland'}</div><h2>Swiss Guide</h2>\n        <p>${r.weak === 1 ? 'Everyday life and the system are taking most of your energy right now. Answers to practical questions about how things work in Switzerland are collected in my free Telegram bot, so you can save your energy for what matters to you.' : 'Answers to practical questions about how things work in Switzerland are collected in my free Telegram bot. That leaves more energy for your inner work.'} The bot is in Russian.</p>\n        <div class=\"invite-links\"><a href=\"https://t.me/swisscompass_bot\" target=\"_blank\" rel=\"noopener\">Open the bot: @swisscompass_bot</a></div></div>` });\n    } }\n  B.push({ html: inviteHtml({ name: myName, country: window.__leadCountry || '', interest: surveyAnswers().interest,\n                              focus: { coach: AREAS[r.weak].focus, psy: 'bring more warmth and understanding into your relationship' } }) });\n  B.push({ html: moreTestsHtml(TEST_META.id) });\n  B.push({ html: authorHtml() });\n  B.push({ html: disclaimerHtml() });\n  r.sName = sName;\n  return B;\n}\nfunction showResult(){\n  $('report').innerHTML = buildBlocks().map(b => b.html).join('');\n  $('quiz').hidden = true; $('result').hidden = false; window.scrollTo(0, 0);\n}\n\n/* ---------- связь с общей анкетой ---------- */\nconst LEAD_HOOKS = {\n  personName: () => myName,\n  fileBase: () => 'Kompas_adaptatsii',\n  fileNames: () => myName ? [myName] : [],\n  payload: () => {\n    const r = last, scores = {};\n    AREAS.forEach((a, k) => scores[a.name] = r.sc[k]);\n    scores['Своя культура'] = r.own; scores['Новая культура'] = r.neu; scores['Индекс адаптации, %'] = r.idx;\n    return { result: r.sName, scores, notes: `в стране: ${YEARS[ctx.years]}; этап: ${STAGES[ctx.stage].name}; опора: ${AREAS[r.strong].name}; рост: ${AREAS[r.weak].name}` };\n  }\n};\n\n/* значки на плитках сфер на стартовой странице */\ndocument.querySelectorAll('.k-roles .role').forEach((el, k) => {\n  const b = el.querySelector('b'); if (!b) return;\n  const w = document.createElement('div'); w.className = 'ri';\n  w.innerHTML = aIcon(k); b.parentNode.insertBefore(w, b); w.appendChild(b);\n});\n", "/* =====================================================================\n   PDF разбора и бланка, форма «Хочешь получать мои материалы?», отправка в Google Таблицу.\n   С 02.10.2026: PDF скачивается сразу, без анкеты. Результаты теста в таблицу НЕ уходят.\n   В таблицу уходят: анонимная запись при скачивании PDF (тест, дата, язык, страна, источник, мини-опрос)\n   и — только если человек сам заполнил форму — его контакты (без результатов).\n   Тест задаёт: TEST_META {id, name}, buildBlocks(), showResult(), LEAD_HOOKS.\n   Страны и PAGE_LANG — в privacy.js. Тексты на четырёх языках — здесь же (LT).\n   ===================================================================== */\nconst LT_ALL = {\n  ru: {\n    dlTitle1: 'Скачать разбор', dlText1: 'Красивый PDF с разбором без вопросов теста: картинки, описания, рекомендации, план на 4 недели и вопросы для размышления.', dlBtn1: 'Скачать разбор',\n    dlTitle: 'Скачать разбор и бланк для записей',\n    dlText: 'Красивый PDF с разбором без вопросов теста: картинки, описания, рекомендации, план на 4 недели и вопросы для размышления. Вместе с ним скачается бланк для записей со всеми вопросами из разбора, чтобы распечатать его и ответить своей рукой.',\n    dlBtn: 'Скачать разбор и бланк', again: 'Пройти заново',\n    wsTitle: 'Бланк для записей', wsText: 'Все вопросы и шаги из твоего разбора с местом для ответов. Его можно распечатать и заполнить от руки.', wsBtn: 'Скачать бланк',\n    matEyebrow: 'По желанию', matTitle: 'Хочешь получать мои материалы?',\n    matText: 'Оставь имя и e-mail, и я буду присылать полезные материалы и рассказывать о новых тестах. Твои ответы на тест остаются только у тебя: мне придут лишь данные из этой формы.',\n    name: 'Имя *', email: 'E-mail *', tg: 'Telegram', tgPh: '@username', wa: 'WhatsApp', waPh: '+41 79 …',\n    consent: link => `Я соглашаюсь, что Ирина Вознесенская получит данные из этой формы, как описано в ${link} *`, consentLink: 'Политике конфиденциальности',\n    news: 'Хочу получать письма с полезными материалами. Отписаться можно в любой момент.',\n    adult: 'Мне есть 18 лет *', send: 'Отправить',\n    errName: 'Напиши, пожалуйста, своё имя.', errEmail: 'Проверь e-mail: похоже, в нём ошибка.', errConsent: 'Чтобы отправить форму, нужно согласие.', errAdult: 'Этот тест предназначен для людей от 18 лет.',\n    sent: 'Спасибо! Данные отправлены.', sendFail: 'Не получилось отправить. Проверь интернет и попробуй ещё раз.',\n    noLib: 'Не получилось загрузить модуль PDF. Проверь интернет и обнови страницу.',\n    making: 'Готовлю PDF…', madeMain: 'Разбор сохранён. Готовлю бланк для записей…',\n    madeBoth: 'Готово! Сохранены два файла: разбор и бланк для записей. Если они не открылись, загляни в папку «Загрузки».',\n    madeOne: 'Разбор сохранён. Если он не открылся, загляни в папку «Загрузки».',\n    madeWsLater: 'Разбор сохранён. Бланк для записей можно скачать кнопкой ниже.',\n    wsMaking: 'Готовлю бланк…', wsDone: 'Бланк сохранён. Распечатай его и пиши от руки.', wsFail: 'Не получилось подготовить бланк. Попробуй ещё раз.',\n    cancel: 'Сохранение отменено.', fail: 'Не получилось подготовить PDF. Попробуй ещё раз.',\n    wsFile: 'Бланк для записей', wsFoot: ' · бланк для записей'\n  },\n  uk: {\n    dlTitle1: 'Завантажити розбір', dlText1: 'Гарний PDF із розбором без питань тесту: малюнки, описи, рекомендації, план на 4 тижні та питання для роздумів.', dlBtn1: 'Завантажити розбір',\n    dlTitle: 'Завантажити розбір і бланк для записів',\n    dlText: 'Гарний PDF із розбором без питань тесту: малюнки, описи, рекомендації, план на 4 тижні та питання для роздумів. Разом із ним завантажиться бланк для записів з усіма питаннями з розбору, щоб роздрукувати його й відповісти від руки.',\n    dlBtn: 'Завантажити розбір і бланк', again: 'Пройти знову',\n    wsTitle: 'Бланк для записів', wsText: 'Усі питання та кроки з твого розбору з місцем для відповідей. Його можна роздрукувати й заповнити від руки.', wsBtn: 'Завантажити бланк',\n    matEyebrow: 'За бажанням', matTitle: 'Хочеш отримувати мої матеріали?',\n    matText: 'Залиш ім’я та e-mail, і я надсилатиму корисні матеріали та розповідатиму про нові тести. Твої відповіді на тест залишаються тільки в тебе: мені прийдуть лише дані з цієї форми.',\n    name: 'Ім’я *', email: 'E-mail *', tg: 'Telegram', tgPh: '@username', wa: 'WhatsApp', waPh: '+380 …',\n    consent: link => `Я погоджуюся, що Ірина Вознесенська отримає дані з цієї форми, як описано в ${link} *`, consentLink: 'Політиці конфіденційності',\n    news: 'Хочу отримувати листи з корисними матеріалами. Відписатися можна будь-коли.',\n    adult: 'Мені є 18 років *', send: 'Надіслати',\n    errName: 'Напиши, будь ласка, своє ім’я.', errEmail: 'Перевір e-mail: схоже, у ньому помилка.', errConsent: 'Щоб надіслати форму, потрібна згода.', errAdult: 'Цей тест призначений для людей від 18 років.',\n    sent: 'Дякую! Дані надіслано.', sendFail: 'Не вдалося надіслати. Перевір інтернет і спробуй ще раз.',\n    noLib: 'Не вдалося завантажити модуль PDF. Перевір інтернет і онови сторінку.',\n    making: 'Готую PDF…', madeMain: 'Розбір збережено. Готую бланк для записів…',\n    madeBoth: 'Готово! Збережено два файли: розбір і бланк для записів. Якщо вони не відкрилися, зазирни в папку «Завантаження».',\n    madeOne: 'Розбір збережено. Якщо він не відкрився, зазирни в папку «Завантаження».',\n    madeWsLater: 'Розбір збережено. Бланк для записів можна завантажити кнопкою нижче.',\n    wsMaking: 'Готую бланк…', wsDone: 'Бланк збережено. Роздрукуй його й пиши від руки.', wsFail: 'Не вдалося підготувати бланк. Спробуй ще раз.',\n    cancel: 'Збереження скасовано.', fail: 'Не вдалося підготувати PDF. Спробуй ще раз.',\n    wsFile: 'Бланк для записів', wsFoot: ' · бланк для записів'\n  },\n  de: {\n    dlTitle1: 'Auswertung herunterladen', dlText1: 'Ein schönes PDF mit deiner Auswertung, ohne die Testfragen: Bilder, Beschreibungen, Empfehlungen, ein Plan für 4 Wochen und Fragen zum Nachdenken.', dlBtn1: 'Auswertung herunterladen',\n    dlTitle: 'Auswertung und Notizblatt herunterladen',\n    dlText: 'Ein schönes PDF mit deiner Auswertung, ohne die Testfragen: Bilder, Beschreibungen, Empfehlungen, ein Plan für 4 Wochen und Fragen zum Nachdenken. Dazu wird ein Notizblatt mit allen Fragen aus der Auswertung heruntergeladen, zum Ausdrucken und Ausfüllen von Hand.',\n    dlBtn: 'Auswertung und Notizblatt herunterladen', again: 'Noch einmal machen',\n    wsTitle: 'Notizblatt', wsText: 'Alle Fragen und Schritte aus deiner Auswertung mit Platz für deine Antworten. Zum Ausdrucken und Ausfüllen von Hand.', wsBtn: 'Notizblatt herunterladen',\n    matEyebrow: 'Freiwillig', matTitle: 'Möchtest du meine Materialien erhalten?',\n    matText: 'Hinterlasse deinen Namen und deine E-Mail, dann schicke ich dir hilfreiche Materialien und erzähle dir von neuen Tests. Deine Antworten im Test bleiben nur bei dir: Ich erhalte nur die Angaben aus diesem Formular.',\n    name: 'Name *', email: 'E-Mail *', tg: 'Telegram', tgPh: '@username', wa: 'WhatsApp', waPh: '+41 79 …',\n    consent: link => `Ich bin einverstanden, dass Iryna Voznesenskaya die Angaben aus diesem Formular erhält, wie in der ${link} beschrieben *`, consentLink: 'Datenschutzerklärung',\n    news: 'Ich möchte E-Mails mit hilfreichen Materialien erhalten. Abmelden ist jederzeit möglich.',\n    adult: 'Ich bin mindestens 18 Jahre alt *', send: 'Senden',\n    errName: 'Bitte gib deinen Namen ein.', errEmail: 'Bitte prüfe deine E-Mail-Adresse.', errConsent: 'Zum Senden brauche ich dein Einverständnis.', errAdult: 'Dieser Test ist für Personen ab 18 Jahren.',\n    sent: 'Danke! Deine Angaben wurden gesendet.', sendFail: 'Das Senden hat nicht geklappt. Prüfe deine Internetverbindung und versuche es noch einmal.',\n    noLib: 'Das PDF-Modul konnte nicht geladen werden. Prüfe deine Internetverbindung und lade die Seite neu.',\n    making: 'PDF wird erstellt…', madeMain: 'Auswertung gespeichert. Das Notizblatt wird erstellt…',\n    madeBoth: 'Fertig! Zwei Dateien wurden gespeichert: die Auswertung und das Notizblatt. Falls sie sich nicht geöffnet haben, schau im Ordner «Downloads» nach.',\n    madeOne: 'Auswertung gespeichert. Falls sie sich nicht geöffnet hat, schau im Ordner «Downloads» nach.',\n    madeWsLater: 'Auswertung gespeichert. Das Notizblatt kannst du unten herunterladen.',\n    wsMaking: 'Notizblatt wird erstellt…', wsDone: 'Notizblatt gespeichert. Druck es aus und schreib von Hand.', wsFail: 'Das Notizblatt konnte nicht erstellt werden. Versuche es noch einmal.',\n    cancel: 'Speichern abgebrochen.', fail: 'Das PDF konnte nicht erstellt werden. Versuche es noch einmal.',\n    wsFile: 'Notizblatt', wsFoot: ' · Notizblatt'\n  },\n  en: {\n    dlTitle1: 'Download your results', dlText1: 'A beautiful PDF with your results, without the test questions: pictures, descriptions, recommendations, a 4-week plan and questions to reflect on.', dlBtn1: 'Download results',\n    dlTitle: 'Download your results and notes sheet',\n    dlText: 'A beautiful PDF with your results, without the test questions: pictures, descriptions, recommendations, a 4-week plan and questions to reflect on. A notes sheet with all the questions from your results is downloaded with it, to print out and answer by hand.',\n    dlBtn: 'Download results and notes sheet', again: 'Take it again',\n    wsTitle: 'Notes sheet', wsText: 'All the questions and steps from your results with space for your answers. Print it out and fill it in by hand.', wsBtn: 'Download notes sheet',\n    matEyebrow: 'Optional', matTitle: 'Would you like to receive my materials?',\n    matText: 'Leave your name and e-mail, and I will send you useful materials and tell you about new tests. Your test answers stay with you only: I only receive the details from this form.',\n    name: 'Name *', email: 'E-mail *', tg: 'Telegram', tgPh: '@username', wa: 'WhatsApp', waPh: '+41 79 …',\n    consent: link => `I agree that Iryna Voznesenskaya receives the details from this form, as described in the ${link} *`, consentLink: 'Privacy policy',\n    news: 'I would like to receive e-mails with useful materials. I can unsubscribe at any time.',\n    adult: 'I am 18 or older *', send: 'Send',\n    errName: 'Please enter your name.', errEmail: 'Please check your e-mail address.', errConsent: 'Your consent is needed to send the form.', errAdult: 'This test is for people aged 18 and over.',\n    sent: 'Thank you! Your details have been sent.', sendFail: 'Sending failed. Check your internet connection and try again.',\n    noLib: 'The PDF module could not be loaded. Check your internet connection and reload the page.',\n    making: 'Preparing the PDF…', madeMain: 'Results saved. Preparing the notes sheet…',\n    madeBoth: 'Done! Two files have been saved: your results and the notes sheet. If they did not open, look in your Downloads folder.',\n    madeOne: 'Results saved. If the file did not open, look in your Downloads folder.',\n    madeWsLater: 'Results saved. You can download the notes sheet with the button below.',\n    wsMaking: 'Preparing the notes sheet…', wsDone: 'Notes sheet saved. Print it out and write by hand.', wsFail: 'The notes sheet could not be prepared. Please try again.',\n    cancel: 'Saving cancelled.', fail: 'The PDF could not be prepared. Please try again.',\n    wsFile: 'Notes sheet', wsFoot: ' · notes sheet'\n  }\n};\nconst L = LT_ALL[PAGE_LANG] || LT_ALL.ru;\nconst HAS_WS = typeof worksheetBlocks === 'function';\nconst ASK_ADULT = (typeof BRAND !== 'undefined' && BRAND === 'psy');   // тесты о паре — только для взрослых\n\nfunction leadFormHtml(){\n  return `<div class=\"blk actions dl-box\" style=\"margin-top:18px\">\n    <h3>${HAS_WS ? L.dlTitle : L.dlTitle1}</h3>\n    <p>${HAS_WS ? L.dlText : L.dlText1}</p>\n    <p class=\"err\" id=\"formErr\" hidden></p>\n    <div class=\"row\">\n      <button class=\"btn\" type=\"button\" id=\"pdfBtn\">${HAS_WS ? L.dlBtn : L.dlBtn1}</button>\n      <button class=\"btn ghost\" type=\"button\" id=\"again\">${L.again}</button>\n    </div>\n    ${HAS_WS ? `<div class=\"ws-offer\" id=\"wsOffer\" hidden><b>${L.wsTitle}</b><span>${L.wsText}</span><button class=\"btn\" type=\"button\" id=\"wsBtn\">${L.wsBtn}</button></div>` : ''}\n    <span class=\"status\" id=\"status\" hidden></span>\n    <p class=\"note keep\" id=\"keepLine\"></p>\n    ${deleteAnswersHtml()}\n  </div>\n  <div class=\"blk mat-box\">\n    <div class=\"eyebrow\">${L.matEyebrow}</div><h3>${L.matTitle}</h3>\n    <p>${L.matText}</p>\n    <form id=\"lead\" class=\"stack\" style=\"gap:12px\" novalidate>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fName\">${L.name}</label><input id=\"fName\" maxlength=\"40\" autocomplete=\"given-name\"></div>\n        <div class=\"field\"><label for=\"fEmail\">${L.email}</label><input id=\"fEmail\" type=\"email\" maxlength=\"80\" autocomplete=\"email\"></div>\n      </div>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fTg\">${L.tg}</label><input id=\"fTg\" maxlength=\"40\" placeholder=\"${L.tgPh}\" autocomplete=\"off\"></div>\n        <div class=\"field\"><label for=\"fWa\">${L.wa}</label><input id=\"fWa\" type=\"tel\" maxlength=\"25\" placeholder=\"${L.waPh}\" autocomplete=\"tel\"></div>\n      </div>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fConsent\"> <span>${L.consent(`<a href=\"${legalUrl('privacy')}\" target=\"_blank\" rel=\"noopener\">${L.consentLink}</a>`)}</span></label>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fNews\"> <span>${L.news}</span></label>\n      ${ASK_ADULT ? `<label class=\"check\"><input type=\"checkbox\" id=\"fAdult\"> <span>${L.adult}</span></label>` : ''}\n      <p class=\"err\" id=\"matErr\" hidden></p>\n      <div class=\"row\"><button class=\"btn\" type=\"submit\" id=\"matBtn\">${L.send}</button></div>\n      <p class=\"note\" id=\"matOk\" hidden></p>\n    </form>\n  </div>`;\n}\ndocument.querySelectorAll('[data-lead]').forEach(el => el.innerHTML = leadFormHtml());\n\nconst el = id => document.getElementById(id);\nfunction setStatus(t){ el('status').textContent = t; el('status').hidden = !t; }\nfunction setErr(t){ el('formErr').textContent = t; el('formErr').hidden = !t; }\nel('again').addEventListener('click', () => { el('result').hidden = true; el('intro').hidden = false; window.scrollTo(0,0); });\n\n/* прежняя анкета хранила контакты; теперь браузер помнит только страну (в мини-опросе) */\nfunction loadLead(){ return { country: surveyCountry(), name: (LEAD_HOOKS.personName && LEAD_HOOKS.personName()) || '' }; }\n\nconst _showResult = showResult;\nshowResult = function(){\n  _showResult();\n  setErr(''); setStatus('');\n  if (el('wsOffer')) el('wsOffer').hidden = true;\n  el('keepLine').textContent = retentionLine();\n  if (!el('fName').value) el('fName').value = (LEAD_HOOKS.personName && LEAD_HOOKS.personName()) || '';\n};\n\n// Чёткость PDF: 3 = около 290 точек на дюйм (хорошо для печати). На слабых телефонах — 2.5.\nconst PDF_SCALE = (/iPhone|iPad|Android/i.test(navigator.userAgent) && (navigator.deviceMemory || 4) < 4) ? 2.5 : 3;\nasync function buildPdf(getBlocks = buildBlocks, foot = null){\n  const stage = el('stage'); stage.innerHTML = '';\n  window.__PDF = true; let blocks; try { blocks = getBlocks(); } finally { window.__PDF = false; }\n  const footText = foot || footerLine();\n  const pages = [];\n  const newPage = () => {\n    const p = document.createElement('div'); p.className = 'pdf-page';\n    p.innerHTML = `<div class=\"strip\"></div><div class=\"pbody\"></div><div class=\"pfoot\"><span>${footText}</span><span class=\"pn\"></span></div>`;\n    stage.appendChild(p); pages.push(p); return p.querySelector('.pbody');\n  };\n  let body = newPage();\n  const mk = b => { const h = document.createElement('div'); h.innerHTML = b.html; return h.firstElementChild; };\n  const over = () => body.scrollHeight > body.clientHeight + 1;\n  const used = new Set();\n  for (let i = 0; i < blocks.length; i++){\n    const b = blocks[i];\n    if (!b.html || used.has(i)) continue;\n    if (b.newPage && body.children.length) body = newPage();\n    const node = mk(b);\n    body.appendChild(node);\n    if (over() && body.children.length > 1){\n      node.remove();\n      // свободное место внизу страницы заполняем небольшими «плавающими» блоками, которые идут дальше (float: true)\n      for (let j = i + 1; j < blocks.length; j++){\n        if (!blocks[j].float || used.has(j) || !blocks[j].html) continue;\n        const f = mk(blocks[j]); body.appendChild(f);\n        if (over()) f.remove(); else used.add(j);\n      }\n      body = newPage(); body.appendChild(node);\n    }\n    if (body.scrollHeight > body.clientHeight + 1 && body.children.length === 1){   // один блок выше страницы — уменьшаем, чтобы ничего не обрезалось\n      const k = body.clientHeight / node.scrollHeight;\n      node.style.transformOrigin = 'top left'; node.style.transform = `scale(${k})`; node.style.width = (100 / k) + '%';\n    }\n  }\n  pages.forEach((p, i) => p.querySelector('.pn').textContent = `${i+1} / ${pages.length}`);\n  if (document.fonts && document.fonts.ready) await document.fonts.ready;\n  const { jsPDF } = window.jspdf;\n  const pdf = new jsPDF({ unit:'pt', format:'a4', compress:true });\n  for (let i = 0; i < pages.length; i++){\n    const canvas = await html2canvas(pages[i], { scale:PDF_SCALE, backgroundColor:'#FFFFFF', useCORS:true, logging:false });\n    if (i) pdf.addPage();\n    pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, 595.28, 841.89, undefined, 'FAST');\n    const pr = pages[i].getBoundingClientRect(), k = 595.28 / pr.width;\n    pages[i].querySelectorAll('a[href]').forEach(a => {\n      if (!/^https?:/.test(a.href)) return;\n      const r = a.getBoundingClientRect();\n      pdf.link((r.left - pr.left) * k, (r.top - pr.top) * k, r.width * k, r.height * k, { url: a.href });\n    });\n  }\n  stage.innerHTML = '';\n  return pdf.output('blob');\n}\n\nlet downloadsCap = null;\n(async () => { try { if (window.claude && window.claude.use) downloadsCap = await window.claude.use('downloads'); } catch(e){ downloadsCap = null; } })();\nasync function saveBlob(blob, filename){\n  if (downloadsCap){ await downloadsCap.save({ filename, data: blob }); return; }\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = filename; a.rel = 'noopener'; document.body.appendChild(a); a.click(); setTimeout(() => a.remove(), 1000);\n  setTimeout(() => URL.revokeObjectURL(url), 60000);\n}\nconst cleanName = s => s.replace(/[\\\\/:*?\"<>|]+/g, ' ').replace(/\\s+/g, ' ').trim();\n\n/* ---------- отправка в таблицу: без результатов теста ---------- */\nfunction basePayload(){\n  const src = new URLSearchParams(location.search);\n  const sv = (typeof surveyAnswers === 'function') ? surveyAnswers() : { heard: [], interest: [] };\n  return {\n    testId: TEST_META.id, testName: TEST_META.name, lang: PAGE_LANG, country: surveyCountry(),\n    heard: sv.heard.join(', '), interest: sv.interest.join(', '),\n    source: src.get('utm_source') || src.get('src') || document.referrer || 'прямой заход'\n  };\n}\nasync function post(payload){\n  if (!ENDPOINT) return;\n  await fetch(ENDPOINT, { method:'POST', mode:'no-cors', headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body: JSON.stringify(payload) });\n}\nlet statSent = false;\nasync function sendStat(){       // анонимно: без имени, e-mail и результатов; один раз за открытие разбора\n  if (statSent) return; statSent = true;\n  try { await post({ kind: 'stat', ...basePayload() }); } catch(e){}\n}\n\n/* ---------- скачать разбор и бланк ---------- */\nel('pdfBtn').addEventListener('click', async () => {\n  setErr('');\n  if (!window.jspdf || !window.html2canvas) return setErr(L.noLib);\n  const btn = el('pdfBtn'); btn.disabled = true; setStatus(L.making);\n  try {\n    sendStat();\n    const blob = await buildPdf();\n    const fname = cleanName([TEST_META.name, ...LEAD_HOOKS.fileNames(), new Date().toLocaleDateString(DATE_LOCALE)].filter(Boolean).join(' — '));\n    await saveBlob(blob, fname + '.pdf');\n    if (!HAS_WS){ setStatus(L.madeOne); return; }\n    el('wsOffer').hidden = false;\n    setStatus(L.madeMain);\n    try { await downloadWorksheet(); setStatus(L.madeBoth); }\n    catch(e2){ setStatus(L.madeWsLater); }\n  } catch(e){\n    setStatus('');\n    setErr(e && e.code === 'declined' ? L.cancel : L.fail);\n  } finally { btn.disabled = false; }\n});\nasync function downloadWorksheet(){\n  const nm = (LEAD_HOOKS.personName && LEAD_HOOKS.personName()) || '';\n  const pair = (typeof WS_PAIR !== 'undefined') ? WS_PAIR : TEST_META.id === 'roza-lyubvi';\n  const blob = await buildPdf(() => { buildBlocks(); return worksheetBlocks({ name: nm, pair }); }, footerLine() + L.wsFoot);\n  const fname = cleanName([L.wsFile, TEST_META.name, nm, new Date().toLocaleDateString(DATE_LOCALE)].filter(Boolean).join(' — '));\n  await saveBlob(blob, fname + '.pdf');\n}\nif (el('wsBtn')) el('wsBtn').addEventListener('click', async () => {\n  const b = el('wsBtn'); b.disabled = true; setErr(''); setStatus(L.wsMaking);\n  try { await downloadWorksheet(); setStatus(L.wsDone); }\n  catch(e){ setStatus(''); setErr(e && e.code === 'declined' ? L.cancel : L.wsFail); }\n  finally { b.disabled = false; }\n});\n\n/* ---------- форма «Хочешь получать мои материалы?» (по желанию) ---------- */\nel('lead').addEventListener('submit', async (ev) => {\n  ev.preventDefault();\n  const err = t => { el('matErr').textContent = t; el('matErr').hidden = !t; };\n  err(''); el('matOk').hidden = true;\n  const lead = { name: el('fName').value.trim(), email: el('fEmail').value.trim(), telegram: el('fTg').value.trim(), whatsapp: el('fWa').value.trim(),\n                 marketing: el('fNews').checked, consent: el('fConsent').checked, adult: ASK_ADULT ? el('fAdult').checked : null };\n  if (!lead.name) return err(L.errName);\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(lead.email)) return err(L.errEmail);\n  if (!lead.consent) return err(L.errConsent);\n  if (ASK_ADULT && !lead.adult) return err(L.errAdult);\n  const b = el('matBtn'); b.disabled = true;\n  try {\n    await post({ kind: 'lead', ...basePayload(), ...lead });\n    el('matOk').textContent = L.sent; el('matOk').hidden = false;\n    el('lead').querySelectorAll('input').forEach(i => { if (i.type === 'checkbox') i.checked = false; else if (i.id !== 'fName') i.value = ''; });\n  } catch(e){ err(L.sendFail); }\n  finally { b.disabled = false; }\n});\nwindow.__buildPdf = buildPdf;\n"]};
